import { useState, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { BillCard } from '../components/BillCard';
import { BillCardSkeleton } from '../components/Skeleton';
import { Search, X, FileX, Plus } from 'lucide-react';
import type { BillView } from '../types/database';
import { groupBillsByDate } from '../lib/utils';
import { useSearchParams, useNavigate } from 'react-router-dom';

type UrgencyFilter = 'all' | 'urgente' | 'quase' | 'ok' | 'pago';

function useBills(orgId: string | undefined) {
  return useQuery({
    queryKey: ['bills', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data, error } = await supabase
        .from('bills_view')
        .select('*')
        .eq('org_id', orgId)
        .order('due_date', { ascending: true });
      if (error) throw error;
      return (data ?? []) as BillView[];
    },
    enabled: !!orgId,
    staleTime: 30_000,
  });
}

export default function BillsPage() {
  const { currentOrg } = useAuth();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [search, setSearch] = useState('');

  const urgenciaParam = (searchParams.get('urgencia') ?? 'all') as UrgencyFilter;

  const { data: bills = [], isLoading } = useBills(currentOrg?.org_id);

  const filtered = useMemo(() => {
    let result = bills;

    // Search
    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(b =>
        b.beneficiary_name?.toLowerCase().includes(q) ||
        b.description?.toLowerCase().includes(q) ||
        b.supplier_name?.toLowerCase().includes(q) ||
        b.barcode_line?.includes(q)
      );
    }

    // Urgency filter
    if (urgenciaParam !== 'all') {
      const urgencyMap: Record<UrgencyFilter, string> = {
        urgente: 'urgent', quase: 'soon', ok: 'ok', pago: 'paid', all: '',
      };
      result = result.filter(b => b.urgency === urgencyMap[urgenciaParam]);
    }

    return result;
  }, [bills, search, urgenciaParam]);

  const groups = groupBillsByDate(filtered);

  const activeFilters: string[] = [];
  if (urgenciaParam !== 'all') activeFilters.push(urgenciaParam);

  function clearFilter(filter: string) {
    if (filter === urgenciaParam) {
      searchParams.delete('urgencia');
      setSearchParams(searchParams);
    }
  }

  const URGENCY_FILTER_OPTIONS: { value: UrgencyFilter; label: string }[] = [
    { value: 'urgente', label: '🔴 Urgente' },
    { value: 'quase', label: '🟡 Quase lá' },
    { value: 'ok', label: '🟢 De boa' },
    { value: 'pago', label: '✓ Pago' },
  ];

  return (
    <main className="page" id="page-bills">
      <header className="page-header">
        <div className="container">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-3)' }}>
            <h1 style={{ fontSize: 'var(--text-xl)', fontWeight: 800 }}>
              Boletos
            </h1>
            <button
              className="btn btn-primary desktop-only"
              onClick={() => navigate('/adicionar')}
              id="bills-desktop-add"
            >
              <Plus size={18} strokeWidth={2.5} />
              <span>Novo boleto</span>
            </button>
          </div>

          {/* Search */}
          <div className="search-wrapper">
            <Search size={18} className="search-icon" aria-hidden="true" />
            <input
              id="bills-search"
              type="search"
              className="input search-input"
              placeholder="Buscar por beneficiário, valor..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              aria-label="Buscar boletos"
            />
          </div>

          {/* Filter chips */}
          {activeFilters.length > 0 && (
            <div style={{ display: 'flex', gap: 'var(--space-2)', flexWrap: 'wrap', marginTop: 'var(--space-3)' }}>
              {activeFilters.map(f => (
                <button
                  key={f}
                  className="chip chip-brand"
                  onClick={() => clearFilter(f)}
                  style={{ cursor: 'pointer', border: 'none' }}
                  aria-label={`Remover filtro: ${f}`}
                >
                  {f}
                  <X size={12} aria-hidden="true" />
                </button>
              ))}
              <button
                className="chip chip-neutral"
                onClick={() => setSearchParams({})}
                style={{ cursor: 'pointer', border: 'none' }}
              >
                Limpar tudo
              </button>
            </div>
          )}
        </div>
      </header>

      <div className="page-content container">
        {/* Filter bar — grade sem scroll */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: 'var(--space-2)',
          marginBottom: 'var(--space-2)',
        }}>
          <button
            className={`filter-chip ${urgenciaParam === 'all' ? 'filter-chip-active' : ''}`}
            onClick={() => { searchParams.delete('urgencia'); setSearchParams(searchParams); }}
          >
            Todos ({bills.length})
          </button>
          {URGENCY_FILTER_OPTIONS.map(opt => {
            const count = bills.filter(b => {
              const map: Record<string, string> = { urgente: 'urgent', quase: 'soon', ok: 'ok', pago: 'paid' };
              return b.urgency === map[opt.value];
            }).length;
            return (
              <button
                key={opt.value}
                className={`filter-chip ${urgenciaParam === opt.value ? 'filter-chip-active' : ''}`}
                onClick={() => { searchParams.set('urgencia', opt.value); setSearchParams(searchParams); }}
                aria-pressed={urgenciaParam === opt.value}
              >
                {opt.label} ({count})
              </button>
            );
          })}
        </div>

        {/* Bills list */}
        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(5)].map((_, i) => <BillCardSkeleton key={i} />)}
          </div>
        ) : filtered.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <FileX
                size={48}
                color="var(--text-muted)"
                style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }}
                aria-hidden="true"
              />
            </div>
            <h2 style={{ fontSize: 'var(--text-lg)' }}>
              {search ? 'Nenhum resultado' : 'Nenhum boleto'}
            </h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              {search
                ? `Nenhum boleto encontrado para "${search}".`
                : 'Tudo em dia por aqui. Adicione um boleto para começar.'
              }
            </p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-5)' }}>
            {groups.map(group => (
              <div key={group.date}>
                <p style={{
                  fontSize: 'var(--text-xs)',
                  color: 'var(--text-muted)',
                  fontWeight: 600,
                  textTransform: 'uppercase',
                  letterSpacing: '0.06em',
                  marginBottom: 'var(--space-2)',
                }}>
                  {group.label}
                </p>
                <div className="bills-group-list">
                  {group.bills.map(bill => <BillCard key={bill.id} bill={bill} />)}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </main>
  );
}
