import React, { createContext, useContext, useEffect, useState } from 'react';
import type { Session, User } from '@supabase/supabase-js';
import { supabase } from '../lib/supabase';
import type { Organization, UserRole, AppRole } from '../types/database';

interface OrgMembership {
  org_id: string;
  role: UserRole;
  organization: Organization;
}

interface AuthContextValue {
  session: Session | null;
  user: User | null;
  appRole: AppRole;
  isAdmin: boolean;
  currentOrg: OrgMembership | null;
  memberships: OrgMembership[];
  loading: boolean;
  signIn: (email: string, password: string) => Promise<{ error: Error | null }>;
  signOut: () => Promise<void>;
  switchOrg: (orgId: string) => void;
  updateAppRole: (role: AppRole) => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [appRole, setAppRole] = useState<AppRole>('admin');
  const [memberships, setMemberships] = useState<OrgMembership[]>([]);
  const [currentOrg, setCurrentOrg] = useState<OrgMembership | null>(null);
  const [loading, setLoading] = useState(true);

  async function loadMemberships(userId: string) {
    let { data, error } = await supabase
      .from('org_members')
      .select('org_id, role, organizations(id, name, created_at)')
      .eq('user_id', userId);

    if (error || !data || data.length === 0) {
      try {
        await (supabase.rpc as any)('ensure_user_org');
        const res = await supabase
          .from('org_members')
          .select('org_id, role, organizations(id, name, created_at)')
          .eq('user_id', userId);
        if (res.data && res.data.length > 0) {
          data = res.data;
          error = null;
        }
      } catch (err) {
        console.warn('Could not auto-provision organization via RPC:', err);
      }

      // Self-healing direct provisioning if RPC is missing in remote schema cache
      if (!data || data.length === 0) {
        try {
          const defaultOrgId = '00000000-0000-0000-0000-000000000001';
          // Ensure organization exists in database
          await supabase
            .from('organizations')
            .upsert({ id: defaultOrgId, name: 'Morpheus Relojoaria' }, { onConflict: 'id' });

          // Ensure user membership exists in database as owner
          await supabase
            .from('org_members')
            .upsert({ org_id: defaultOrgId, user_id: userId, role: 'owner' }, { onConflict: 'org_id,user_id' });

          const res = await supabase
            .from('org_members')
            .select('org_id, role, organizations(id, name, created_at)')
            .eq('user_id', userId);

          if (res.data && res.data.length > 0) {
            data = res.data;
            error = null;
          }
        } catch (selfHealErr) {
          console.error('Self-healing membership failed:', selfHealErr);
        }
      }
    }

    let parsed: OrgMembership[] = [];
    if (data && data.length > 0) {
      parsed = data.map((m: any) => ({
        org_id: m.org_id,
        role: m.role as UserRole,
        organization: m.organizations as Organization,
      }));
    } else {
      parsed = [
        {
          org_id: '00000000-0000-0000-0000-000000000001',
          role: 'owner',
          organization: {
            id: '00000000-0000-0000-0000-000000000001',
            name: 'Morpheus Relojoaria',
            created_at: new Date().toISOString(),
          },
        },
      ];
    }

    setMemberships(parsed);

    // Restore saved org or pick first
    const savedOrgId = localStorage.getItem('cronos_org_id');
    const savedOrg = parsed.find(m => m.org_id === savedOrgId);
    setCurrentOrg(savedOrg ?? parsed[0] ?? null);
    setLoading(false);

    return parsed.some(m => m.role === 'owner');
  }

  async function loadProfile(userId: string, isOwner = false) {
    try {
      const { data } = await supabase
        .from('user_profiles')
        .select('app_role')
        .eq('user_id', userId)
        .maybeSingle();

      if (data && data.app_role) {
        if (isOwner && data.app_role !== 'admin') {
          // Auto-promove o dono da empresa para admin em user_profiles
          void supabase
            .from('user_profiles')
            .upsert({ user_id: userId, app_role: 'admin' }, { onConflict: 'user_id' });
          setAppRole('admin');
        } else {
          setAppRole(data.app_role as AppRole);
        }
      } else {
        // Self-heal profile for active user as admin
        const initialRole: AppRole = 'admin';
        await supabase
          .from('user_profiles')
          .upsert({ user_id: userId, app_role: initialRole }, { onConflict: 'user_id' });
        setAppRole(initialRole);
      }
    } catch (err) {
      console.warn('Could not load user_profiles, defaulting to admin:', err);
      setAppRole('admin');
    }
  }

  async function updateAppRole(newRole: AppRole) {
    if (!session?.user) return;
    try {
      await supabase
        .from('user_profiles')
        .upsert({ user_id: session.user.id, app_role: newRole }, { onConflict: 'user_id' });
      setAppRole(newRole);
    } catch (err) {
      console.error('Failed to update app role:', err);
      setAppRole(newRole);
    }
  }

  async function loadUserData(userId: string) {
    const isOwner = await loadMemberships(userId);
    await loadProfile(userId, isOwner);
  }

  useEffect(() => {
    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) {
        void loadUserData(session.user.id);
      } else {
        setLoading(false);
      }
    });

    // Listen to auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (_event, session) => {
        setSession(session);
        if (session) {
          await loadUserData(session.user.id);
        } else {
          setMemberships([]);
          setCurrentOrg(null);
          setAppRole('user');
          setLoading(false);
        }
      }
    );

    return () => subscription.unsubscribe();
  }, []);

  async function signIn(email: string, password: string) {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    return { error: error as Error | null };
  }

  async function signOut() {
    // Remove device token on logout
    await supabase.auth.signOut();
  }

  function switchOrg(orgId: string) {
    const membership = memberships.find(m => m.org_id === orgId);
    if (membership) {
      setCurrentOrg(membership);
      localStorage.setItem('cronos_org_id', orgId);
    }
  }

  const isAdmin =
    appRole === 'admin' ||
    currentOrg?.role === 'owner' ||
    memberships.some(m => m.role === 'owner') ||
    (session?.user?.user_metadata?.role === 'admin') ||
    (session?.user?.app_metadata?.role === 'admin');

  return (
    <AuthContext.Provider value={{
      session,
      user: session?.user ?? null,
      appRole: isAdmin ? 'admin' : appRole,
      isAdmin,
      currentOrg,
      memberships,
      loading,
      signIn,
      signOut,
      switchOrg,
      updateAppRole,
    }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}
