import { useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from './Toast';

export function ForcedNotificationListener() {
  const { currentOrg } = useAuth();
  const { toast } = useToast();

  useEffect(() => {
    // Web Audio chime for forced alert
    function playAlertChime() {
      try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        if (!AudioContextClass) return;
        const ctx = new AudioContextClass();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
        osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.15); // A5
        gain.gain.setValueAtTime(0.3, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start();
        osc.stop(ctx.currentTime + 0.4);
      } catch (e) {
        // Audio might be blocked if no user interaction yet
      }
    }

    const channel = supabase
      .channel('cronos-broadcast')
      .on('broadcast', { event: 'forced_push' }, (payload: any) => {
        const data = payload?.payload;
        if (!data) return;

        // Check if targeted to all or matching user org
        if (data.target_scope === 'org' && data.target_org_id && currentOrg?.org_id !== data.target_org_id) {
          return;
        }

        // Play chime
        playAlertChime();

        // Display in-app toast
        toast(`📢 ${data.title}: ${data.body}`, 'info');

        // Display native push if supported and granted
        if ('Notification' in window && Notification.permission === 'granted') {
          try {
            if (navigator.serviceWorker?.controller) {
              navigator.serviceWorker.ready.then((reg) => {
                reg.showNotification(data.title, {
                  body: data.body,
                  icon: './icons/icon-192.png',
                  badge: './icons/icon-192.png',
                  vibrate: [300, 100, 300, 100, 300],
                  tag: 'forced-' + Date.now(),
                  requireInteraction: true,
                } as any);
              });
            } else {
              new Notification(data.title, {
                body: data.body,
                icon: './icons/icon-192.png',
              });
            }
          } catch (err) {
            console.warn('Native notification display error:', err);
          }
        }
      })
      .subscribe();

    const handlePushReceived = (e: any) => {
      const { title, body } = e.detail || {};
      if (title || body) {
        playAlertChime();
        toast(`🔔 ${title}: ${body}`, 'info');
      }
    };
    window.addEventListener('cronos:push-received', handlePushReceived);

    return () => {
      supabase.removeChannel(channel);
      window.removeEventListener('cronos:push-received', handlePushReceived);
    };
  }, [currentOrg?.org_id, toast]);

  return null;
}
