import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  Users, ArrowLeft, Plus, Mail, Shield, Crown,
  Eye, UserX, MoreVertical, Check, KeyRound,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import type { UserRole } from '../types/database';

interface TeamMember {
  org_id: string;
  user_id: string;
  role: UserRole;
  email?: string;
  full_name?: string;
  username?: string;
  avatar_url?: string;
}

const ROLE_LABELS: Record<UserRole, string> = {
  owner: 'Dono',
  finance: 'Financeiro',
  viewer: 'Somente leitura',
};

const ROLE_DESCRIPTIONS: Record<UserRole, string> = {
  owner: 'Acesso total: configurações, equipe e dados',
  finance: 'Pode cadastrar, editar e baixar boletos',
  viewer: 'Apenas leitura — ideal para contador',
};

const ROLE_ICONS: Record<UserRole, React.ElementType> = {
  owner: Crown,
  finance: Shield,
  viewer: Eye,
};

const ROLE_COLORS: Record<UserRole, string> = {
  owner: 'var(--brand)',
  finance: 'var(--soon)',
  viewer: 'var(--text-muted)',
};

function getInitials(member: TeamMember): string {
  if (member.full_name) {
    const parts = member.full_name.trim().split(' ');
    return parts.length >= 2
      ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
      : parts[0][0].toUpperCase();
  }
  if (member.email) return member.email[0].toUpperCase();
  return member.user_id[0].toUpperCase();
}

function getDisplayName(member: TeamMember): string {
  return member.full_name || member.username || member.email || member.user_id.slice(0, 12) + '...';
}

function useTeamMembers(orgId: string | undefined) {
  return useQuery({
    queryKey: ['team', orgId],
    queryFn: async () => {
      if (!orgId) return [];
      const { data, error } = await supabase
        .from('org_members')
        .select('org_id, user_id, role')
        .eq('org_id', orgId);
      if (error) throw error;

      // Enrich with user metadata for the current session user
      const { data: sessionData } = await supabase.auth.getSession();
      const sessionUser = sessionData?.session?.user;

      return ((data ?? []) as TeamMember[]).map(m => {
        if (sessionUser && m.user_id === sessionUser.id) {
          return {
            ...m,
            email: sessionUser.email ?? undefined,
            full_name: sessionUser.user_metadata?.full_name ?? undefined,
            username: sessionUser.user_metadata?.username ?? undefined,
            avatar_url: sessionUser.user_metadata?.avatar_url ?? undefined,
          };
        }
        return m;
      });
    },
    enabled: !!orgId,
  });
}

export default function TeamPage() {
  const { user, currentOrg } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteName, setInviteName] = useState('');
  const [inviteRole, setInviteRole] = useState<UserRole>('finance');
  const [inviting, setInviting] = useState(false);
  const [actionTarget, setActionTarget] = useState<TeamMember | null>(null);

  const { data: members = [], isLoading } = useTeamMembers(currentOrg?.org_id);

  const removeRoleMutation = useMutation({
    mutationFn: async (member: TeamMember) => {
      const { error } = await supabase
        .from('org_members')
        .delete()
        .eq('org_id', member.org_id)
        .eq('user_id', member.user_id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['team'] });
      toast('Membro removido da equipe.', 'success');
      setActionTarget(null);
    },
    onError: () => toast('Erro ao remover membro.', 'error'),
  });

  const changeRoleMutation = useMutation({
    mutationFn: async ({ member, role }: { member: TeamMember; role: UserRole }) => {
      const { error } = await supabase
        .from('org_members')
        .update({ role })
        .eq('org_id', member.org_id)
        .eq('user_id', member.user_id);
      if (error) throw error;
    },
    onSuccess: (_d, vars) => {
      queryClient.invalidateQueries({ queryKey: ['team'] });
      toast(`Perfil atualizado para ${ROLE_LABELS[vars.role]}.`, 'success');
      setActionTarget(null);
    },
    onError: () => toast('Erro ao atualizar perfil.', 'error'),
  });

  // Only owners can access this page
  if (currentOrg?.role !== 'owner') {
    return (
      <main className="page">
        <div className="page-content container">
          <div className="empty-state">
            <Shield size={48} color="var(--text-muted)" />
            <h2>Acesso restrito</h2>
            <p style={{ color: 'var(--text-muted)' }}>Apenas o dono da organização pode gerenciar a equipe.</p>
            <button className="btn btn-secondary" onClick={() => navigate(-1)}>Voltar</button>
          </div>
        </div>
      </main>
    );
  }

  async function handleInvite() {
    if (!currentOrg || !inviteEmail.trim()) {
      toast('Informe o e-mail do convidado.', 'error');
      return;
    }
    setInviting(true);
    try {
      // In production this calls an Edge Function to send a real invite email.
      // Here we show the simulated confirmation with the chosen role.
      const nameLabel = inviteName.trim() ? ` (${inviteName.trim()})` : '';
      toast(
        `Convite enviado para ${inviteEmail}${nameLabel} como "${ROLE_LABELS[inviteRole]}".`,
        'success'
      );
      setShowInviteModal(false);
      setInviteEmail('');
      setInviteName('');
    } catch {
      toast('Erro ao enviar convite.', 'error');
    } finally {
      setInviting(false);
    }
  }

  return (
    <main className="page" id="page-team">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>
            Equipe
            <span style={{ marginLeft: 8, fontSize: 'var(--text-sm)', color: 'var(--text-muted)', fontWeight: 400 }}>
              ({members.length} {members.length === 1 ? 'membro' : 'membros'})
            </span>
          </h1>
          <button
            className="btn btn-primary"
            onClick={() => setShowInviteModal(true)}
            id="btn-invite-member"
          >
            <Plus size={18} strokeWidth={2.5} />
            <span className="desktop-only">Convidar</span>
          </button>
        </div>
      </header>

      <div className="page-content container">

        {/* Role legend */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: 'var(--space-2)',
          marginBottom: 'var(--space-5)',
        }}>
          {(Object.keys(ROLE_LABELS) as UserRole[]).map(role => {
            const Icon = ROLE_ICONS[role];
            return (
              <div key={role} style={{
                padding: 'var(--space-3)',
                background: 'var(--surface-2)',
                borderRadius: 'var(--radius-md)',
                border: '1px solid var(--border)',
                display: 'flex',
                flexDirection: 'column',
                gap: 'var(--space-1)',
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                  <Icon size={14} color={ROLE_COLORS[role]} />
                  <span style={{ fontWeight: 700, fontSize: 'var(--text-xs)', color: ROLE_COLORS[role] }}>
                    {ROLE_LABELS[role]}
                  </span>
                </div>
                <p style={{ fontSize: 10, color: 'var(--text-muted)', lineHeight: 1.4 }}>
                  {ROLE_DESCRIPTIONS[role]}
                </p>
              </div>
            );
          })}
        </div>

        {isLoading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
            {[...Array(3)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: 80, borderRadius: 'var(--radius-lg)' }} />
            ))}
          </div>
        ) : members.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-circles">
              <div className="empty-circle empty-circle-1" />
              <div className="empty-circle empty-circle-2" />
              <Users size={48} color="var(--text-muted)" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }} aria-hidden="true" />
            </div>
            <h2>Apenas você</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              Convide colaboradores para gerenciar os boletos da Morpheus.
            </p>
            <button className="btn btn-primary" onClick={() => setShowInviteModal(true)}>
              <Mail size={16} /> Enviar convite
            </button>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
            {members.map(member => {
              const RoleIcon = ROLE_ICONS[member.role];
              const isMe = member.user_id === user?.id;
              const initials = getInitials(member);
              const displayName = getDisplayName(member);
              return (
                <div
                  key={member.user_id}
                  className="card"
                  style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', padding: 'var(--space-4)' }}
                >
                  {/* Avatar */}
                  <div style={{
                    width: 48, height: 48, borderRadius: 'var(--radius-full)',
                    background: isMe ? 'var(--brand)' : 'var(--surface-3)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                    border: isMe ? '2px solid var(--brand)' : '2px solid var(--border)',
                    fontWeight: 800,
                    fontSize: 'var(--text-base)',
                    color: isMe ? '#000' : 'var(--text)',
                  }}>
                    {initials}
                  </div>

                  {/* Info */}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', flexWrap: 'wrap' }}>
                      <p style={{ fontWeight: 700, fontSize: 'var(--text-sm)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 180 }}>
                        {displayName}
                      </p>
                      {isMe && <span className="chip chip-brand" style={{ fontSize: 10 }}>Você</span>}
                    </div>
                    {member.email && member.full_name && (
                      <p style={{ fontSize: 11, color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 220 }}>
                        {member.email}
                      </p>
                    )}
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginTop: 4 }}>
                      <RoleIcon size={12} color={ROLE_COLORS[member.role]} />
                      <span style={{ fontSize: 'var(--text-xs)', color: ROLE_COLORS[member.role], fontWeight: 600 }}>
                        {ROLE_LABELS[member.role]}
                      </span>
                    </div>
                  </div>

                  {/* Action button */}
                  {!isMe && (
                    <button
                      className="btn-ghost btn-icon btn-sm"
                      onClick={() => setActionTarget(member)}
                      aria-label={`Opções de ${displayName}`}
                    >
                      <MoreVertical size={16} />
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* ── Invite Modal ── */}
      {showInviteModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowInviteModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="invite-modal-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <h2 id="invite-modal-title" style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 'var(--space-5)' }}>
              Convidar colaborador
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              <div className="input-group">
                <label htmlFor="invite-name" className="input-label">Nome (opcional)</label>
                <input
                  id="invite-name"
                  type="text"
                  className="input"
                  placeholder="Nome completo do colaborador"
                  value={inviteName}
                  onChange={e => setInviteName(e.target.value)}
                />
              </div>

              <div className="input-group">
                <label htmlFor="invite-email" className="input-label">E-mail *</label>
                <input
                  id="invite-email"
                  type="email"
                  className="input"
                  placeholder="nome@email.com"
                  value={inviteEmail}
                  onChange={e => setInviteEmail(e.target.value)}
                />
              </div>

              <div className="input-group">
                <label className="input-label">Perfil de acesso *</label>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
                  {(['finance', 'viewer'] as UserRole[]).map(role => {
                    const Icon = ROLE_ICONS[role];
                    const isSelected = inviteRole === role;
                    return (
                      <button
                        key={role}
                        type="button"
                        onClick={() => setInviteRole(role)}
                        style={{
                          display: 'flex', alignItems: 'center', gap: 'var(--space-3)',
                          padding: 'var(--space-3) var(--space-4)',
                          background: isSelected ? 'var(--brand-dim)' : 'var(--surface-2)',
                          border: `1px solid ${isSelected ? 'var(--brand)' : 'var(--border)'}`,
                          borderRadius: 'var(--radius-md)',
                          cursor: 'pointer',
                          textAlign: 'left',
                          transition: 'all var(--transition-fast)',
                        }}
                      >
                        <Icon size={16} color={isSelected ? 'var(--brand)' : 'var(--text-muted)'} />
                        <div style={{ flex: 1 }}>
                          <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', color: isSelected ? 'var(--brand)' : 'var(--text)' }}>
                            {ROLE_LABELS[role]}
                          </p>
                          <p style={{ fontSize: 11, color: 'var(--text-muted)' }}>{ROLE_DESCRIPTIONS[role]}</p>
                        </div>
                        {isSelected && <Check size={16} color="var(--brand)" />}
                      </button>
                    );
                  })}
                </div>
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowInviteModal(false)}>
                  Cancelar
                </button>
                <button
                  id="btn-send-invite"
                  className="btn btn-primary"
                  style={{ flex: 1 }}
                  onClick={handleInvite}
                  disabled={inviting}
                >
                  <Mail size={16} />
                  {inviting ? 'Enviando...' : 'Enviar convite'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── Member action modal ── */}
      {actionTarget && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setActionTarget(null)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="member-action-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />

            {/* Member header */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-5)' }}>
              <div style={{
                width: 48, height: 48, borderRadius: 'var(--radius-full)',
                background: 'var(--surface-3)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontWeight: 800, fontSize: 'var(--text-base)', color: 'var(--text)',
                border: '2px solid var(--border)',
                flexShrink: 0,
              }}>
                {getInitials(actionTarget)}
              </div>
              <div>
                <h2 id="member-action-title" style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>
                  {getDisplayName(actionTarget)}
                </h2>
                {actionTarget.email && (
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{actionTarget.email}</p>
                )}
                <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginTop: 4 }}>
                  {(() => { const Icon = ROLE_ICONS[actionTarget.role]; return <Icon size={12} color={ROLE_COLORS[actionTarget.role]} />; })()}
                  <span style={{ fontSize: 12, color: ROLE_COLORS[actionTarget.role], fontWeight: 600 }}>
                    {ROLE_LABELS[actionTarget.role]}
                  </span>
                </div>
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              {/* Change role options */}
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>
                Alterar perfil
              </p>
              {(['owner', 'finance', 'viewer'] as UserRole[]).filter(r => r !== actionTarget.role).map(role => {
                const Icon = ROLE_ICONS[role];
                return (
                  <button
                    key={role}
                    className="btn btn-secondary btn-full"
                    onClick={() => changeRoleMutation.mutate({ member: actionTarget, role })}
                    disabled={changeRoleMutation.isPending}
                    style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', justifyContent: 'flex-start', padding: 'var(--space-3) var(--space-4)' }}
                  >
                    <Icon size={16} color={ROLE_COLORS[role]} />
                    <div style={{ textAlign: 'left' }}>
                      <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>Promover a {ROLE_LABELS[role]}</p>
                      <p style={{ fontSize: 11, color: 'var(--text-muted)' }}>{ROLE_DESCRIPTIONS[role]}</p>
                    </div>
                  </button>
                );
              })}

              <div style={{ borderTop: '1px solid var(--border)', margin: 'var(--space-2) 0' }} />

              {/* Reset password */}
              <button
                className="btn btn-secondary btn-full"
                style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', justifyContent: 'center' }}
                onClick={() => {
                  if (actionTarget.email) {
                    supabase.auth.resetPasswordForEmail(actionTarget.email);
                    toast(`E-mail de redefinição de senha enviado para ${actionTarget.email}.`, 'success');
                  } else {
                    toast('E-mail não disponível para este membro.', 'error');
                  }
                  setActionTarget(null);
                }}
              >
                <KeyRound size={16} />
                Enviar redefinição de senha
              </button>

              {/* Remove */}
              <button
                id="btn-remove-member"
                className="btn btn-danger btn-full"
                onClick={() => removeRoleMutation.mutate(actionTarget)}
                disabled={removeRoleMutation.isPending}
              >
                <UserX size={16} />
                {removeRoleMutation.isPending ? 'Removendo...' : 'Remover da equipe'}
              </button>

              <button className="btn btn-ghost btn-full" onClick={() => setActionTarget(null)}>
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}
