import { initializeApp, getApps, getApp } from 'firebase/app';
import { getMessaging, getToken, onMessage, isSupported, type Messaging } from 'firebase/messaging';
import { supabase } from './supabase';
import { getPlatform } from './utils';

const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID,
};

export const firebaseApp = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();

let messagingInstance: Messaging | null = null;
let foregroundListenerRegistered = false;

// Safe accessor for FCM messaging instance (checks browser compatibility)
export async function getMessagingInstance(): Promise<Messaging | null> {
  if (messagingInstance) return messagingInstance;
  if (typeof window === 'undefined') return null;

  try {
    const supported = await isSupported();
    if (supported) {
      messagingInstance = getMessaging(firebaseApp);
      return messagingInstance;
    }
  } catch (err) {
    console.warn('[FCM] Messaging support check failed:', err);
  }
  return null;
}

// Export messaging for backwards compatibility
export let messaging: Messaging | null = null;
try {
  if (typeof window !== 'undefined') {
    messaging = getMessaging(firebaseApp);
  }
} catch {
  // Ignored in unsupported environments
}

export function isPushNotificationSupported(): boolean {
  return (
    typeof window !== 'undefined' &&
    'Notification' in window &&
    'serviceWorker' in navigator
  );
}

// Requests notification permission and retrieves the FCM Web Push Token
export async function requestNotificationPermission(): Promise<string | null> {
  if (!isPushNotificationSupported()) {
    console.warn('[FCM] Push notifications are not supported in this browser.');
    return null;
  }

  try {
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') {
      console.warn('[FCM] Notification permission was not granted:', permission);
      return null;
    }

    const registration = await navigator.serviceWorker.ready;
    const msg = await getMessagingInstance();
    if (!msg) {
      console.warn('[FCM] Could not get FCM messaging instance.');
      return null;
    }

    const tokenOptions: { serviceWorkerRegistration: ServiceWorkerRegistration; vapidKey?: string } = {
      serviceWorkerRegistration: registration,
    };

    if (import.meta.env.VITE_FIREBASE_VAPID_KEY) {
      tokenOptions.vapidKey = import.meta.env.VITE_FIREBASE_VAPID_KEY;
    }

    const token = await getToken(msg, tokenOptions);
    return token;
  } catch (error) {
    console.error('[FCM] Error requesting notification permission and token:', error);
    return null;
  }
}

// Registers and configures device in FCM, device_tokens, and notification_prefs
export async function configureFcmDevice(
  userId: string,
  orgId?: string
): Promise<{
  success: boolean;
  token: string | null;
  permission: NotificationPermission | 'unsupported';
  error?: string;
}> {
  if (!isPushNotificationSupported()) {
    return {
      success: false,
      token: null,
      permission: 'unsupported',
      error: 'Notificações não são suportadas neste navegador.',
    };
  }

  try {
    const currentPermission = Notification.permission;
    let token: string | null = null;

    if (currentPermission === 'granted') {
      const registration = await navigator.serviceWorker.ready;
      const msg = await getMessagingInstance();
      if (msg) {
        const tokenOptions: { serviceWorkerRegistration: ServiceWorkerRegistration; vapidKey?: string } = {
          serviceWorkerRegistration: registration,
        };
        if (import.meta.env.VITE_FIREBASE_VAPID_KEY) {
          tokenOptions.vapidKey = import.meta.env.VITE_FIREBASE_VAPID_KEY;
        }
        token = await getToken(msg, tokenOptions);
      }
    } else {
      token = await requestNotificationPermission();
    }

    if (!token) {
      return {
        success: false,
        token: null,
        permission: Notification.permission,
        error: Notification.permission === 'denied'
          ? 'Permissão negada pelo usuário.'
          : 'Não foi possível gerar o token FCM.',
      };
    }

    const platform = getPlatform();

    // 1. Sync device token with Supabase device_tokens table
    const { error: tokenError } = await supabase.from('device_tokens').upsert(
      {
        user_id: userId,
        fcm_token: token,
        platform,
        last_seen: new Date().toISOString(),
      },
      { onConflict: 'fcm_token' }
    );

    if (tokenError) {
      console.warn('[FCM] device_tokens upsert notice, executing recovery:', tokenError);
      // Fallback in case of previous account conflict
      await supabase.from('device_tokens').delete().eq('fcm_token', token);
      await supabase.from('device_tokens').insert({
        user_id: userId,
        fcm_token: token,
        platform,
        last_seen: new Date().toISOString(),
      });
    }

    // 2. Ensure notification preferences has push active for this organization
    if (orgId) {
      await supabase.from('notification_prefs').upsert(
        {
          user_id: userId,
          org_id: orgId,
          push: true,
          days_before: [7, 2, 0],
          send_hour: 9,
        },
        { onConflict: 'user_id,org_id' }
      );
    }

    // 3. Cache token locally
    localStorage.setItem('cronos_fcm_token', token);

    // 4. Initialize foreground message handler
    await initForegroundNotificationHandler();

    return {
      success: true,
      token,
      permission: 'granted',
    };
  } catch (err: any) {
    console.error('[FCM] Error configuring FCM for device:', err);
    return {
      success: false,
      token: null,
      permission: Notification.permission,
      error: err?.message || 'Falha ao registrar aparelho no FCM.',
    };
  }
}

// Handles notifications received while the app is in the foreground
export async function initForegroundNotificationHandler(
  onReceive?: (payload: any) => void
) {
  if (foregroundListenerRegistered) return;

  try {
    const msg = await getMessagingInstance();
    if (!msg) return;

    foregroundListenerRegistered = true;
    onMessage(msg, (payload) => {
      console.log('[FCM] Foreground notification received:', payload);

      const title = payload.notification?.title || (payload.data?.title as string) || 'Cronos — Morpheus';
      const body = payload.notification?.body || (payload.data?.body as string) || 'Novo alerta de boleto disponível.';

      if (onReceive) {
        onReceive({ title, body, payload });
      }

      // Dispatch global window event for components to react
      window.dispatchEvent(
        new CustomEvent('cronos:push-received', {
          detail: { title, body, payload },
        })
      );

      // If document is in background or tab switched, show browser notification
      if (document.hidden && 'Notification' in window && Notification.permission === 'granted') {
        if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
          navigator.serviceWorker.ready.then((reg) => {
            reg.showNotification(title, {
              body,
              icon: './icons/icon-192.png',
              badge: './icons/icon-192.png',
              vibrate: [200, 100, 200],
              data: payload.data,
              tag: (payload.data?.bill_id as string) || 'cronos',
            } as any);
          });
        }
      }
    });
  } catch (err) {
    console.warn('[FCM] Could not initialize foreground handler:', err);
  }
}

export { onMessage };
