import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { ArrowLeft, Save, AlertCircle, Wand2, Tag, Building2, ExternalLink } from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../contexts/AuthContext';
import { useToast } from '../../components/Toast';
import { validateBarcodeLine, extractBoletoData } from '../../lib/utils';
import { useQueryClient, useQuery } from '@tanstack/react-query';
import type { Supplier, Category } from '../../types/database';

const billSchema = z.object({
  beneficiary_name: z.string().min(1, 'Informe o beneficiário'),
  description: z.string().optional(),
  amount: z.string().refine(v => !isNaN(parseFloat(v.replace(',', '.'))) && parseFloat(v.replace(',', '.')) > 0, {
    message: 'Valor deve ser maior que zero',
  }),
  due_date: z.string().min(1, 'Informe o vencimento'),
  barcode_line: z.string().optional().refine(
    val => !val || validateBarcodeLine(val),
    { message: 'Linha digitável inválida (deve ter 47 ou 48 dígitos)' }
  ),
  supplier_id: z.string().optional(),
  category_id: z.string().optional(),
});

type BillFormData = z.infer<typeof billSchema>;

export default function ManualBillPage() {
  const { currentOrg, user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const prefill = (location.state as any)?.prefill || {};
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [loading, setLoading] = useState(false);

  const { data: suppliers = [] } = useQuery({
    queryKey: ['suppliers', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase.from('suppliers').select('*').eq('org_id', currentOrg.org_id).order('name');
      return (data ?? []) as Supplier[];
    },
    enabled: !!currentOrg?.org_id,
  });

  const { data: categories = [] } = useQuery({
    queryKey: ['categories', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase.from('categories').select('*').eq('org_id', currentOrg.org_id).order('name');
      return (data ?? []) as Category[];
    },
    enabled: !!currentOrg?.org_id,
  });

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<BillFormData>({
    resolver: zodResolver(billSchema) as any,
    defaultValues: {
      beneficiary_name: prefill.beneficiary_name || '',
      description: prefill.description || '',
      amount: prefill.amount || '',
      due_date: prefill.due_date || '',
      barcode_line: prefill.barcode_line || '',
      supplier_id: prefill.supplier_id || '',
      category_id: prefill.category_id || '',
    },
  });

  const watchedBarcode = watch('barcode_line');

  function handleAutoFillFromBarcode() {
    if (!watchedBarcode) return;
    const parsed = extractBoletoData(watchedBarcode);
    if (!parsed) {
      toast('Código incompleto ou inválido para extração automática.', 'error');
      return;
    }
    if (parsed.amount) setValue('amount', String(parsed.amount));
    if (parsed.dueDate) setValue('due_date', parsed.dueDate);
    if (parsed.bankName && !watch('beneficiary_name')) {
      setValue('beneficiary_name', parsed.bankName);
    }
    toast('Dados preenchidos a partir da linha digitável!', 'success');
  }

  async function onSubmit(data: BillFormData) {
    if (!currentOrg || !user) {
      toast('Organização não identificada. Recarregue a página e tente novamente.', 'error');
      return;
    }
    setLoading(true);

    try {
      const parsedAmount = parseFloat(String(data.amount).replace(',', '.'));

      // RF-06: Detecção de duplicidade por linha digitável
      if (data.barcode_line) {
        const cleaned = data.barcode_line.replace(/\D/g, '');
        const { data: existing } = await supabase
          .from('bills')
          .select('id')
          .eq('org_id', currentOrg.org_id)
          .eq('barcode_line', cleaned)
          .neq('status', 'canceled')
          .maybeSingle();

        if (existing) {
          setLoading(false);
          toast('Já existe um boleto com essa linha digitável cadastrado.', 'error');
          return;
        }
      }

      // RF-06: Detecção de duplicidade por (mesmo valor, vencimento e beneficiário)
      const { data: duplicateBill } = await supabase
        .from('bills')
        .select('id')
        .eq('org_id', currentOrg.org_id)
        .eq('amount', parsedAmount)
        .eq('due_date', data.due_date)
        .ilike('beneficiary_name', data.beneficiary_name.trim())
        .neq('status', 'canceled')
        .maybeSingle();

      if (duplicateBill) {
        setLoading(false);
        toast('Atenção: Já existe um boleto idêntico com este mesmo beneficiário, valor e data de vencimento.', 'error');
        return;
      }

      // Failsafe: Ensure membership is recognized in DB before inserting
      try {
        await supabase
          .from('org_members')
          .upsert(
            { org_id: currentOrg.org_id, user_id: user.id, role: currentOrg.role || 'owner' },
            { onConflict: 'org_id,user_id' }
          );
      } catch (memberErr) {
        console.warn('Pre-insert membership check note:', memberErr);
      }

      const { data: newBill, error } = await supabase
        .from('bills')
        .insert({
          org_id: currentOrg.org_id,
          beneficiary_name: data.beneficiary_name.trim(),
          description: data.description?.trim() || null,
          amount: parsedAmount,
          due_date: data.due_date,
          barcode_line: data.barcode_line ? data.barcode_line.replace(/\D/g, '') : null,
          supplier_id: data.supplier_id || null,
          category_id: data.category_id || null,
          created_by: user.id,
        })
        .select()
        .single();

      if (error || !newBill) {
        console.error('Error inserting bill into Supabase:', error);
        throw error || new Error('Falha ao registrar boleto no banco');
      }

      await queryClient.invalidateQueries({ queryKey: ['bills'] });
      await queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      toast('Boleto cadastrado com sucesso!', 'success');
      navigate(`/boletos/${newBill.id}`);
    } catch (err: any) {
      console.error('Submit error in ManualBillPage:', err);
      const msg = err?.message || '';
      if (msg.includes('row-level security')) {
        toast('Erro de permissão: seu usuário ainda não está sincronizado na organização. Saia e entre novamente.', 'error');
      } else {
        toast(msg ? `Erro ao salvar: ${msg}` : 'Erro ao salvar o boleto. Tente novamente.', 'error');
      }
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="page" id="page-manual-bill">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700 }}>Novo boleto</h1>
        </div>
      </header>

      <div className="page-content container">
        <form onSubmit={handleSubmit(onSubmit)} noValidate>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>

            {/* Beneficiary */}
            <div className="input-group">
              <label htmlFor="beneficiary" className="input-label">Beneficiário *</label>
              <input
                id="beneficiary"
                type="text"
                className={`input ${errors.beneficiary_name ? 'input-error' : ''}`}
                placeholder="Ex: Casio do Brasil"
                {...register('beneficiary_name')}
              />
              {errors.beneficiary_name && (
                <span className="input-error-msg" role="alert">
                  <AlertCircle size={12} style={{ display: 'inline', marginRight: 4 }} />
                  {errors.beneficiary_name.message}
                </span>
              )}
            </div>

            {/* Description */}
            <div className="input-group">
              <label htmlFor="description" className="input-label">Descrição</label>
              <input
                id="description"
                type="text"
                className="input"
                placeholder="Ex: Pedido #1234 — coleção outono"
                {...register('description')}
              />
            </div>

            {/* Amount + Due date side by side */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>
              <div className="input-group">
                <label htmlFor="amount" className="input-label">Valor (R$) *</label>
                <input
                  id="amount"
                  type="number"
                  step="0.01"
                  min="0"
                  className={`input amount ${errors.amount ? 'input-error' : ''}`}
                  placeholder="0,00"
                  {...register('amount')}
                />
                {errors.amount && (
                  <span className="input-error-msg" role="alert">{errors.amount.message}</span>
                )}
              </div>

              <div className="input-group">
                <label htmlFor="due_date" className="input-label">Vencimento *</label>
                <input
                  id="due_date"
                  type="date"
                  className={`input ${errors.due_date ? 'input-error' : ''}`}
                  {...register('due_date')}
                />
                {errors.due_date && (
                  <span className="input-error-msg" role="alert">{errors.due_date.message}</span>
                )}
              </div>
            </div>

            {/* Supplier + Category side by side */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>
              {/* Supplier */}
              <div className="input-group">
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-1)' }}>
                  <label htmlFor="supplier_id" className="input-label" style={{ marginBottom: 0 }}>
                    <Building2 size={12} style={{ display: 'inline', marginRight: 4, color: 'var(--text-muted)' }} />
                    Fornecedor
                  </label>
                  {suppliers.length === 0 && (
                    <button
                      type="button"
                      className="btn-ghost"
                      onClick={() => navigate('/fornecedores')}
                      style={{ fontSize: 10, padding: '1px 6px', color: 'var(--brand)', height: 'auto', minHeight: 0, display: 'flex', alignItems: 'center', gap: 3 }}
                    >
                      <ExternalLink size={10} />
                      Cadastrar
                    </button>
                  )}
                </div>
                <select
                  id="supplier_id"
                  className="input"
                  {...register('supplier_id')}
                  disabled={suppliers.length === 0}
                >
                  <option value="">{suppliers.length === 0 ? '— Nenhum cadastrado —' : 'Nenhum'}</option>
                  {suppliers.map(s => (
                    <option key={s.id} value={s.id}>{s.name}</option>
                  ))}
                </select>
              </div>

              {/* Category */}
              <div className="input-group">
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-1)' }}>
                  <label htmlFor="category_id" className="input-label" style={{ marginBottom: 0 }}>
                    <Tag size={12} style={{ display: 'inline', marginRight: 4, color: 'var(--text-muted)' }} />
                    Categoria
                  </label>
                  {categories.length === 0 && (
                    <button
                      type="button"
                      className="btn-ghost"
                      onClick={() => navigate('/categorias')}
                      style={{ fontSize: 10, padding: '1px 6px', color: 'var(--brand)', height: 'auto', minHeight: 0, display: 'flex', alignItems: 'center', gap: 3 }}
                    >
                      <ExternalLink size={10} />
                      Cadastrar
                    </button>
                  )}
                </div>
                <select
                  id="category_id"
                  className="input"
                  {...register('category_id')}
                  disabled={categories.length === 0}
                >
                  <option value="">{categories.length === 0 ? '— Nenhuma cadastrada —' : 'Nenhuma'}</option>
                  {categories.map(c => (
                    <option key={c.id} value={c.id}>{c.icon ?? ''} {c.name}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Barcode */}
            <div className="input-group">
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <label htmlFor="barcode" className="input-label" style={{ marginBottom: 0 }}>Linha digitável (opcional)</label>
                {watchedBarcode && watchedBarcode.replace(/\D/g, '').length >= 44 && (
                  <button
                    type="button"
                    className="btn-ghost"
                    onClick={handleAutoFillFromBarcode}
                    style={{ fontSize: 11, padding: '2px 8px', color: 'var(--brand)', height: 'auto', minHeight: 0 }}
                  >
                    <Wand2 size={12} style={{ marginRight: 4 }} />
                    Detectar valor e data
                  </button>
                )}
              </div>
              <input
                id="barcode"
                type="text"
                className={`input ${errors.barcode_line ? 'input-error' : ''}`}
                placeholder="Cole aqui os 47 ou 48 dígitos"
                inputMode="numeric"
                {...register('barcode_line')}
              />
              {errors.barcode_line && (
                <span className="input-error-msg" role="alert">
                  <AlertCircle size={12} style={{ display: 'inline', marginRight: 4 }} />
                  {errors.barcode_line.message}
                </span>
              )}
              <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)' }}>
                Permite pagar direto no app do banco com um toque.
              </span>
            </div>

            <div style={{ height: 'var(--space-4)' }} />

            <button
              id="btn-save-bill"
              type="submit"
              className="btn btn-primary btn-full btn-lg"
              disabled={loading}
              aria-busy={loading}
            >
              <Save size={20} aria-hidden="true" />
              {loading ? 'Salvando...' : 'Salvar boleto'}
            </button>
          </div>
        </form>
      </div>
    </main>
  );
}
