import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Sparkles,
  Send,
  Bot,
  User as UserIcon,
  Plus,
  ArrowRight,
  Image as ImageIcon,
  X,
  CheckCircle2,
  Zap,
  Cpu,
  FileCheck,
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { formatCurrency, formatDate, daysToDate } from '../lib/utils';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { askFinancialAI, extractBoletoFromImageAi, type ExtractedBoletoAi, type FinancialContext, OPENAI_CONFIG } from '../lib/openai';
import { parseAssistantCommand, type AssistantDraftBill } from '../lib/assistantParser';
import { useToast } from '../components/Toast';
import type { BillView, Supplier, Category } from '../types/database';

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  createdAt: string;
  source?: 'parser' | 'ai';
  model?: string;
  tokensUsed?: number;
  imageUrl?: string;
  action?: {
    label: string;
    route?: string;
    executeAction?: 'mark_paid' | 'create_bill';
    billId?: string;
    draftBill?: AssistantDraftBill;
  };
  metrics?: {
    total?: number;
    count?: number;
    highlight?: string;
  };
  draftBill?: AssistantDraftBill;
  detectedBoleto?: ExtractedBoletoAi;
}

export default function AssistantPage() {
  const { currentOrg, user } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState<string>('Processando...');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [conversationId, setConversationId] = useState<string | null>(null);

  // Staged image for upload
  const [stagedImage, setStagedImage] = useState<{ file: File; dataUrl: string } | null>(null);
  const [executingActionId, setExecutingActionId] = useState<string | null>(null);

  // Load all bills for the active organization to compute real financial numbers
  const { data: bills = [] } = useQuery({
    queryKey: ['bills_all', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase
        .from('bills_view')
        .select('*')
        .eq('org_id', currentOrg.org_id)
        .order('due_date', { ascending: true });
      return (data ?? []) as BillView[];
    },
    enabled: !!currentOrg?.org_id,
  });

  const { data: suppliers = [] } = useQuery({
    queryKey: ['suppliers_all', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase
        .from('suppliers')
        .select('*')
        .eq('org_id', currentOrg.org_id);
      return (data ?? []) as Supplier[];
    },
    enabled: !!currentOrg?.org_id,
  });

  const { data: categories = [] } = useQuery({
    queryKey: ['categories_all', currentOrg?.org_id],
    queryFn: async () => {
      if (!currentOrg?.org_id) return [];
      const { data } = await supabase
        .from('categories')
        .select('*')
        .eq('org_id', currentOrg.org_id);
      return (data ?? []) as Category[];
    },
    enabled: !!currentOrg?.org_id,
  });

  // Initialize or fetch conversation
  useEffect(() => {
    if (!currentOrg || !user) return;

    async function initConversation() {
      try {
        const { data: convs } = await supabase
          .from('ai_conversations')
          .select('id, title')
          .eq('org_id', currentOrg!.org_id)
          .eq('user_id', user!.id)
          .order('updated_at', { ascending: false })
          .limit(1);

        if (convs && convs.length > 0) {
          const activeConv = convs[0];
          setConversationId(activeConv.id);

          // Fetch messages
          const { data: dbMessages } = await supabase
            .from('ai_messages')
            .select('*')
            .eq('conversation_id', activeConv.id)
            .order('created_at', { ascending: true });

          if (dbMessages && dbMessages.length > 0) {
            setMessages(
              dbMessages.map(m => {
                const meta = (m.metadata as Record<string, any>) || {};
                return {
                  id: m.id,
                  role: m.role as 'user' | 'assistant',
                  content: m.content,
                  createdAt: m.created_at,
                  source: meta.source || (m.role === 'assistant' ? 'ai' : undefined),
                  model: meta.model,
                  tokensUsed: m.tokens_used,
                  imageUrl: meta.imageUrl,
                  action: meta.action,
                  metrics: meta.metrics,
                  draftBill: meta.draftBill,
                  detectedBoleto: meta.detectedBoleto,
                };
              })
            );
            return;
          }
        } else {
          // Create initial conversation
          const { data: newConv } = await supabase
            .from('ai_conversations')
            .insert({
              org_id: currentOrg!.org_id,
              user_id: user!.id,
              title: 'Atendimento Financeiro Cronos',
            })
            .select()
            .single();

          if (newConv) setConversationId(newConv.id);
        }
      } catch (err) {
        console.warn('AI conversation init fallback:', err);
      }

      // Initial greeting if no messages
      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: `Olá! Sou o Assistente Inteligente do Cronos, conectado aos boletos e fluxo de caixa da **${currentOrg?.organization?.name || 'sua empresa'}**.\n\n⚡ **Economia Inteligente**: Consultas financeiras e tarefas diretas são resolvidas instantaneamente pelo motor local sem consumir tokens.\n🤖 **OpenAI (${OPENAI_CONFIG.model})**: Ativada para perguntas analíticas ou para extrair dados de fotos e boletos anexados!`,
          createdAt: new Date().toISOString(),
          source: 'parser',
        },
      ]);
    }

    initConversation();
  }, [currentOrg, user]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  // Handle image selection
  function handleImagePick(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/') && !file.name.endsWith('.pdf')) {
      toast('Por favor, selecione uma imagem (PNG, JPG, WEBP) do boleto.', 'error');
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      setStagedImage({
        file,
        dataUrl: reader.result as string,
      });
    };
    reader.readAsDataURL(file);

    // Reset input value so same file can be re-selected if removed
    e.target.value = '';
  }

  // Handle direct message send
  async function handleSend(textToSend?: string) {
    const query = (textToSend || input).trim();
    const hasImage = !!stagedImage;

    if ((!query && !hasImage) || loading) return;

    setInput('');
    const imageToSend = stagedImage;
    setStagedImage(null);

    const now = new Date();
    const userMsgId = 'user-' + now.getTime();
    const userMsg: ChatMessage = {
      id: userMsgId,
      role: 'user',
      content: query || (hasImage ? 'Extrair dados e cadastrar boleto desta imagem.' : ''),
      createdAt: now.toISOString(),
      imageUrl: imageToSend?.dataUrl,
    };

    setMessages(prev => [...prev, userMsg]);
    setLoading(true);

    // Persist user message in DB
    if (conversationId) {
      void supabase.from('ai_messages').insert({
        conversation_id: conversationId,
        role: 'user',
        content: userMsg.content,
        metadata: { imageUrl: userMsg.imageUrl ? 'has_image' : undefined } as any,
      }).then(() => {}, (err: unknown) => console.warn('Supabase message persist user:', err));
    }

    try {
      // ─────────────────────────────────────────────────────────────
      // CASO 1: UPLOAD DE IMAGEM -> USA VISÃO IA DA OPENAI (gpt-5.4-mini)
      // ─────────────────────────────────────────────────────────────
      if (hasImage && imageToSend) {
        setLoadingStatus(`Lendo imagem com visão computacional (${OPENAI_CONFIG.model})...`);
        const aiExtraction = await extractBoletoFromImageAi(imageToSend.dataUrl, query);

        const resNow = new Date();
        const extracted = aiExtraction.boleto;

        // Auto-match supplier if exists in DB
        const matchedSup = suppliers.find(s =>
          extracted.beneficiary_name.toLowerCase().includes(s.name.toLowerCase()) ||
          s.name.toLowerCase().includes(extracted.beneficiary_name.toLowerCase())
        );

        // Auto-match category
        const matchedCat = categories.find(c =>
          extracted.suggested_category &&
          c.name.toLowerCase().includes(extracted.suggested_category.toLowerCase())
        );

        const draftBill: AssistantDraftBill = {
          beneficiary_name: extracted.beneficiary_name,
          amount: extracted.amount,
          due_date: extracted.due_date,
          barcode_line: extracted.barcode_line,
          description: extracted.description || 'Boleto extraído por IA da foto',
          supplier_id: matchedSup?.id || null,
          category_id: matchedCat?.id || null,
        };

        const assistantMsg: ChatMessage = {
          id: 'assistant-' + resNow.getTime(),
          role: 'assistant',
          content: `Extração concluída com sucesso via **${OPENAI_CONFIG.model}**!\n\n` +
            `• **Beneficiário**: ${extracted.beneficiary_name}\n` +
            `• **Valor**: ${extracted.amount ? formatCurrency(extracted.amount) : 'Não identificado'}\n` +
            `• **Vencimento**: ${extracted.due_date ? formatDate(extracted.due_date) : 'Não identificado'}\n` +
            (extracted.barcode_line ? `• **Linha digitável**: \`${extracted.barcode_line}\`\n` : '') +
            `• **Precisão estimada**: ${extracted.confidence}%`,
          createdAt: resNow.toISOString(),
          source: 'ai',
          model: OPENAI_CONFIG.model,
          tokensUsed: aiExtraction.tokensUsed,
          draftBill,
          detectedBoleto: extracted,
          action: {
            label: 'Confirmar e Cadastrar Boleto',
            executeAction: 'create_bill',
            draftBill,
          },
          metrics: extracted.amount ? { total: extracted.amount, highlight: 'Boleto detectado' } : undefined,
        };

        setMessages(prev => [...prev, assistantMsg]);

        if (conversationId) {
          void supabase.from('ai_messages').insert({
            conversation_id: conversationId,
            role: 'assistant',
            content: assistantMsg.content,
            tokens_used: aiExtraction.tokensUsed,
            metadata: {
              source: 'ai',
              model: OPENAI_CONFIG.model,
              draftBill,
              detectedBoleto: extracted,
              action: assistantMsg.action,
              metrics: assistantMsg.metrics,
            } as any,
          }).then(() => {}, (err: unknown) => console.warn('Supabase message persist:', err));
        }

        setLoading(false);
        return;
      }

      // ─────────────────────────────────────────────────────────────
      // CASO 2: PARSER DETERMINÍSTICO LOCAL (SEM IA / ZERO CONSUMO)
      // ─────────────────────────────────────────────────────────────
      setLoadingStatus('Analisando comando...');
      const parseResult = parseAssistantCommand(query, bills, suppliers, categories);

      if (parseResult.type === 'handled') {
        const parsed = parseResult.response;
        const resNow = new Date();

        // Breve delay estético (150ms) para sensação orgânica sem gastar IA
        await new Promise(r => setTimeout(r, 150));

        const assistantMsg: ChatMessage = {
          id: 'assistant-' + resNow.getTime(),
          role: 'assistant',
          content: parsed.content,
          createdAt: resNow.toISOString(),
          source: 'parser',
          action: parsed.action,
          metrics: parsed.metrics,
          draftBill: parsed.draftBill,
        };

        setMessages(prev => [...prev, assistantMsg]);

        if (conversationId) {
          void supabase.from('ai_messages').insert({
            conversation_id: conversationId,
            role: 'assistant',
            content: parsed.content,
            tokens_used: 0,
            metadata: {
              source: 'parser',
              action: parsed.action,
              metrics: parsed.metrics,
              draftBill: parsed.draftBill,
            } as any,
          }).then(() => {}, (err: unknown) => console.warn('Supabase message persist:', err));
        }

        setLoading(false);
        return;
      }

      // ─────────────────────────────────────────────────────────────
      // CASO 3: DÚVIDA / ANÁLISE COMPLEXA -> OPENAI (gpt-5.4-mini)
      // ─────────────────────────────────────────────────────────────
      setLoadingStatus(`Consultando inteligência financeira (${OPENAI_CONFIG.model})...`);

      // Construir contexto financeiro em tempo real da organização
      const overdueBills = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) < 0);
      const totalOverdue = overdueBills.reduce((s, b) => s + Number(b.amount), 0);
      const pendingBills = bills.filter(b => b.status === 'pending');
      const totalPending = pendingBills.reduce((s, b) => s + Number(b.amount), 0);
      const dueTodayCount = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) === 0).length;
      const dueWeekCount = bills.filter(b => {
        if (b.status !== 'pending') return false;
        const d = daysToDate(b.due_date);
        return d >= 0 && d <= 7;
      }).length;

      const nowMonth = new Date().getMonth();
      const nowYear = new Date().getFullYear();
      const monthBills = bills.filter(b => {
        const d = new Date(b.due_date + 'T00:00:00');
        return d.getMonth() === nowMonth && d.getFullYear() === nowYear;
      });
      const currentMonthPending = monthBills.filter(b => b.status === 'pending').reduce((s, b) => s + Number(b.amount), 0);
      const currentMonthPaid = monthBills.filter(b => b.status === 'paid').reduce((s, b) => s + (b.paid_amount ?? Number(b.amount)), 0);

      const financialContext: FinancialContext = {
        orgName: currentOrg?.organization?.name || 'Morpheus Relojoaria',
        totalPending,
        totalOverdue,
        overdueCount: overdueBills.length,
        dueTodayCount,
        dueWeekCount,
        currentMonthPending,
        currentMonthPaid,
        topOverdueBills: overdueBills.slice(0, 5).map(b => ({
          beneficiary: b.beneficiary_name || 'Boleto',
          amount: Number(b.amount),
          due_date: formatDate(b.due_date),
        })),
        topUpcomingBills: pendingBills
          .filter(b => daysToDate(b.due_date) >= 0)
          .slice(0, 5)
          .map(b => ({
            beneficiary: b.beneficiary_name || 'Boleto',
            amount: Number(b.amount),
            due_date: formatDate(b.due_date),
          })),
        suppliersList: suppliers.map(s => s.name),
        categoriesList: categories.map(c => c.name),
      };

      const historyForAi = messages
        .filter(m => m.id !== 'welcome')
        .map(m => ({ role: m.role, content: m.content }));

      const aiResponse = await askFinancialAI(historyForAi, query, financialContext);

      const resNow = new Date();
      const assistantMsg: ChatMessage = {
        id: 'assistant-' + resNow.getTime(),
        role: 'assistant',
        content: aiResponse.text,
        createdAt: resNow.toISOString(),
        source: 'ai',
        model: aiResponse.model,
        tokensUsed: aiResponse.tokensUsed,
      };

      setMessages(prev => [...prev, assistantMsg]);

      if (conversationId) {
        void supabase.from('ai_messages').insert({
          conversation_id: conversationId,
          role: 'assistant',
          content: aiResponse.text,
          tokens_used: aiResponse.tokensUsed,
          metadata: {
            source: 'ai',
            model: aiResponse.model,
          } as any,
        }).then(() => {}, (err: unknown) => console.warn('Supabase message persist:', err));
      }
    } catch (err: any) {
      console.error('Erro no assistente:', err);
      const resNow = new Date();
      setMessages(prev => [
        ...prev,
        {
          id: 'error-' + resNow.getTime(),
          role: 'assistant',
          content: `⚠️ Não foi possível processar sua solicitação no momento (${err.message || 'Erro de comunicação'}). Tente novamente ou use os comandos rápidos.`,
          createdAt: resNow.toISOString(),
          source: 'parser',
        },
      ]);
    } finally {
      setLoading(false);
    }
  }

  // Action execution: Confirm Payment directly from chat
  async function handleConfirmPayment(billId: string, actionKey: string) {
    if (!currentOrg || executingActionId) return;
    setExecutingActionId(actionKey);

    try {
      const targetBill = bills.find(b => b.id === billId);
      const paidVal = targetBill ? Number(targetBill.amount) : 0;

      const { error } = await supabase
        .from('bills')
        .update({
          status: 'paid',
          paid_at: new Date().toISOString(),
          paid_amount: paidVal,
        })
        .eq('id', billId)
        .eq('org_id', currentOrg.org_id);

      if (error) throw error;

      toast('Boleto marcado como quitado com sucesso!', 'success');
      await queryClient.invalidateQueries({ queryKey: ['bills_all'] });
      await queryClient.invalidateQueries({ queryKey: ['bills'] });
      await queryClient.invalidateQueries({ queryKey: ['dashboard'] });

      // Append confirmation in chat
      setMessages(prev => [
        ...prev,
        {
          id: 'sys-' + Date.now(),
          role: 'assistant',
          content: `✅ **Baixa registrada com sucesso!** O boleto de ${targetBill?.beneficiary_name || 'conta'} (${formatCurrency(paidVal)}) foi dado como quitado.`,
          createdAt: new Date().toISOString(),
          source: 'parser',
          action: { label: 'Ver lista atualizada', route: '/boletos' },
        },
      ]);
    } catch (err: any) {
      console.error('Falha ao dar baixa:', err);
      toast('Erro ao dar baixa no boleto: ' + (err.message || ''), 'error');
    } finally {
      setExecutingActionId(null);
    }
  }

  // Action execution: Save Draft Bill directly from chat
  async function handleSaveDraftBill(draft: AssistantDraftBill, actionKey: string) {
    if (!currentOrg || !user || executingActionId) return;

    if (!draft.beneficiary_name || !draft.amount || !draft.due_date) {
      toast('Dados incompletos para cadastro automático. Abra o formulário completo.', 'error');
      navigate('/boletos/novo');
      return;
    }

    setExecutingActionId(actionKey);

    try {
      // Duplicate barcode check if barcode line is present
      if (draft.barcode_line) {
        const cleaned = draft.barcode_line.replace(/\D/g, '');
        const { data: existing } = await supabase
          .from('bills')
          .select('id')
          .eq('org_id', currentOrg.org_id)
          .eq('barcode_line', cleaned)
          .neq('status', 'canceled')
          .maybeSingle();

        if (existing) {
          toast('Já existe um boleto com esta mesma linha digitável cadastrado.', 'error');
          setExecutingActionId(null);
          return;
        }
      }

      const { data: newBill, error } = await supabase
        .from('bills')
        .insert({
          org_id: currentOrg.org_id,
          beneficiary_name: draft.beneficiary_name.trim(),
          amount: draft.amount,
          due_date: draft.due_date,
          barcode_line: draft.barcode_line ? draft.barcode_line.replace(/\D/g, '') : null,
          supplier_id: draft.supplier_id || null,
          category_id: draft.category_id || null,
          description: draft.description || 'Cadastrado via Assistente Cronos',
          created_by: user.id,
        })
        .select()
        .single();

      if (error || !newBill) throw error || new Error('Falha ao salvar boleto');

      toast('Boleto cadastrado com sucesso!', 'success');
      await queryClient.invalidateQueries({ queryKey: ['bills_all'] });
      await queryClient.invalidateQueries({ queryKey: ['bills'] });
      await queryClient.invalidateQueries({ queryKey: ['dashboard'] });

      // Append confirmation in chat
      setMessages(prev => [
        ...prev,
        {
          id: 'sys-' + Date.now(),
          role: 'assistant',
          content: `🎉 **Boleto cadastrado no Cronos!**\n\n• **Beneficiário**: ${newBill.beneficiary_name}\n• **Valor**: ${formatCurrency(Number(newBill.amount))}\n• **Vencimento**: ${formatDate(newBill.due_date)}`,
          createdAt: new Date().toISOString(),
          source: 'parser',
          action: { label: 'Abrir detalhes do boleto', route: `/boletos/${newBill.id}` },
        },
      ]);
    } catch (err: any) {
      console.error('Falha ao cadastrar boleto:', err);
      toast('Erro ao cadastrar boleto: ' + (err.message || ''), 'error');
    } finally {
      setExecutingActionId(null);
    }
  }

  const promptSuggestions = [
    'O que vence hoje?',
    'Quais boletos estão atrasados?',
    'Quanto tenho para pagar essa semana?',
    'Resumo do mês atual',
    'Quanto paguei de juros?',
    'Ajuda e comandos',
  ];

  return (
    <main
      className="page"
      id="page-assistant"
      style={{ display: 'flex', flexDirection: 'column', height: '100dvh', background: 'var(--bg)' }}
    >
      {/* Header */}
      <header className="page-header" style={{ flexShrink: 0 }}>
        <div className="container" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div
              style={{
                width: 38,
                height: 38,
                borderRadius: 'var(--radius-full)',
                background: 'linear-gradient(135deg, var(--brand) 0%, #d4af37 100%)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0 2px 10px rgba(212, 175, 55, 0.3)',
              }}
            >
              <Sparkles size={20} color="var(--on-brand)" />
            </div>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <h1 style={{ fontSize: 'var(--text-base)', fontWeight: 700, margin: 0 }}>Assistente Cronos</h1>
                <span
                  style={{
                    fontSize: 10,
                    fontWeight: 700,
                    padding: '1px 6px',
                    borderRadius: 999,
                    background: 'rgba(212, 175, 55, 0.15)',
                    color: 'var(--brand)',
                    border: '1px solid rgba(212, 175, 55, 0.3)',
                  }}
                >
                  {OPENAI_CONFIG.model}
                </span>
              </div>
              <span style={{ fontSize: 11, color: 'var(--ok)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--ok)' }} />
                Motor Local + Visão IA Ativos
              </span>
            </div>
          </div>

          <button
            className="btn-ghost btn-icon"
            onClick={() => {
              setMessages([
                {
                  id: 'welcome-' + Date.now(),
                  role: 'assistant',
                  content: 'Nova consulta iniciada. Digite uma pergunta, envie um comando de boleto ou anexe uma foto!',
                  createdAt: new Date().toISOString(),
                  source: 'parser',
                },
              ]);
            }}
            title="Nova conversa"
            aria-label="Nova conversa"
          >
            <Plus size={20} />
          </button>
        </div>
      </header>

      {/* Chat Messages Body */}
      <div
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '16px 0',
        }}
      >
        <div className="container" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {messages.map(msg => {
            const isUser = msg.role === 'user';
            return (
              <div
                key={msg.id}
                style={{
                  display: 'flex',
                  gap: 10,
                  flexDirection: isUser ? 'row-reverse' : 'row',
                  alignItems: 'flex-start',
                }}
              >
                {/* Avatar */}
                <div
                  style={{
                    width: 32,
                    height: 32,
                    borderRadius: 'var(--radius-full)',
                    background: isUser ? 'var(--surface-2)' : 'var(--brand-dim)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    flexShrink: 0,
                  }}
                >
                  {isUser ? (
                    <UserIcon size={16} color="var(--text-muted)" />
                  ) : (
                    <Bot size={18} color="var(--brand)" />
                  )}
                </div>

                {/* Message bubble */}
                <div
                  style={{
                    maxWidth: '85%',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 8,
                  }}
                >
                  {/* Badge de origem (Motor Local vs OpenAI) */}
                  {!isUser && msg.source && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, alignSelf: 'flex-start' }}>
                      {msg.source === 'parser' ? (
                        <span
                          style={{
                            fontSize: 10,
                            fontWeight: 600,
                            padding: '1px 7px',
                            borderRadius: 999,
                            background: 'rgba(74, 222, 128, 0.12)',
                            color: 'var(--ok)',
                            border: '1px solid rgba(74, 222, 128, 0.25)',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 3,
                          }}
                        >
                          <Zap size={10} /> Motor Local (Sem IA)
                        </span>
                      ) : (
                        <span
                          style={{
                            fontSize: 10,
                            fontWeight: 600,
                            padding: '1px 7px',
                            borderRadius: 999,
                            background: 'rgba(168, 85, 247, 0.12)',
                            color: '#c084fc',
                            border: '1px solid rgba(168, 85, 247, 0.3)',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 3,
                          }}
                        >
                          <Cpu size={10} /> OpenAI {msg.model || OPENAI_CONFIG.model}
                          {msg.tokensUsed ? ` (${msg.tokensUsed} tokens)` : ''}
                        </span>
                      )}
                    </div>
                  )}

                  {/* Imagem enviada pelo usuário */}
                  {msg.imageUrl && (
                    <div
                      style={{
                        borderRadius: 'var(--radius-lg)',
                        overflow: 'hidden',
                        maxWidth: 240,
                        border: '1px solid var(--border)',
                        background: 'var(--surface-2)',
                      }}
                    >
                      <img
                        src={msg.imageUrl}
                        alt="Documento do boleto"
                        style={{ width: '100%', height: 'auto', display: 'block', maxHeight: 200, objectFit: 'cover' }}
                      />
                    </div>
                  )}

                  {/* Conteúdo textual da mensagem */}
                  <div
                    style={{
                      padding: '12px 16px',
                      borderRadius: isUser ? '16px 4px 16px 16px' : '4px 16px 16px 16px',
                      background: isUser ? 'var(--brand)' : 'var(--surface)',
                      color: isUser ? 'var(--on-brand)' : 'var(--text)',
                      border: isUser ? 'none' : '1px solid var(--border)',
                      fontSize: 'var(--text-sm)',
                      lineHeight: 1.5,
                      whiteSpace: 'pre-line',
                      boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
                    }}
                  >
                    {msg.content}
                  </div>

                  {/* Cartão de Boleto Detectado (se presente) */}
                  {msg.draftBill && (
                    <div
                      style={{
                        background: 'var(--surface-2)',
                        border: '1px solid var(--brand)',
                        borderRadius: 'var(--radius-lg)',
                        padding: 12,
                        display: 'flex',
                        flexDirection: 'column',
                        gap: 10,
                      }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          <FileCheck size={16} color="var(--brand)" />
                          <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--brand)' }}>
                            Boleto Identificado
                          </span>
                        </div>
                        {msg.detectedBoleto?.confidence && (
                          <span
                            style={{
                              fontSize: 10,
                              fontWeight: 700,
                              padding: '2px 6px',
                              borderRadius: 999,
                              background: 'rgba(74, 222, 128, 0.15)',
                              color: 'var(--ok)',
                            }}
                          >
                            Precisão: {msg.detectedBoleto.confidence}%
                          </span>
                        )}
                      </div>

                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, fontSize: 12 }}>
                        <div>
                          <span style={{ color: 'var(--text-muted)', fontSize: 11 }}>Beneficiário</span>
                          <p style={{ margin: 0, fontWeight: 600, color: '#fff' }}>
                            {msg.draftBill.beneficiary_name}
                          </p>
                        </div>
                        <div>
                          <span style={{ color: 'var(--text-muted)', fontSize: 11 }}>Valor</span>
                          <p style={{ margin: 0, fontWeight: 700, color: 'var(--brand)' }}>
                            {msg.draftBill.amount ? formatCurrency(msg.draftBill.amount) : 'Pendente'}
                          </p>
                        </div>
                        <div>
                          <span style={{ color: 'var(--text-muted)', fontSize: 11 }}>Vencimento</span>
                          <p style={{ margin: 0, fontWeight: 600, color: '#fff' }}>
                            {msg.draftBill.due_date ? formatDate(msg.draftBill.due_date) : 'Pendente'}
                          </p>
                        </div>
                        {msg.draftBill.barcode_line && (
                          <div>
                            <span style={{ color: 'var(--text-muted)', fontSize: 11 }}>Código</span>
                            <p style={{ margin: 0, fontSize: 10, fontFamily: 'monospace', color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                              {msg.draftBill.barcode_line}
                            </p>
                          </div>
                        )}
                      </div>

                      {/* Botões de Ação para o Boleto */}
                      <div style={{ display: 'flex', gap: 8, marginTop: 4 }}>
                        <button
                          className="btn-primary"
                          onClick={() => handleSaveDraftBill(msg.draftBill!, msg.id)}
                          disabled={executingActionId === msg.id}
                          style={{
                            flex: 1,
                            fontSize: 12,
                            padding: '8px 12px',
                            justifyContent: 'center',
                          }}
                        >
                          <CheckCircle2 size={14} style={{ marginRight: 6 }} />
                          {executingActionId === msg.id ? 'Cadastrando...' : 'Salvar no Cronos'}
                        </button>

                        <button
                          className="btn-secondary"
                          onClick={() => {
                            const pre = msg.draftBill;
                            navigate('/boletos/novo', {
                              state: {
                                beneficiary_name: pre?.beneficiary_name,
                                amount: pre?.amount ? String(pre.amount) : '',
                                due_date: pre?.due_date || '',
                                barcode_line: pre?.barcode_line || '',
                              },
                            });
                          }}
                          style={{ fontSize: 12, padding: '8px 10px' }}
                          title="Revisar no formulário"
                        >
                          Revisar
                        </button>
                      </div>
                    </div>
                  )}

                  {/* Highlight metric card */}
                  {msg.metrics?.total !== undefined && !msg.draftBill && (
                    <div
                      style={{
                        background: 'var(--surface-2)',
                        border: '1px solid var(--border)',
                        borderRadius: 'var(--radius-md)',
                        padding: '10px 14px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                      }}
                    >
                      <div>
                        <span style={{ fontSize: 11, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                          {msg.metrics.highlight || 'Total Identificado'}
                        </span>
                        <p style={{ fontSize: 'var(--text-base)', fontWeight: 700, color: 'var(--brand)', margin: 0 }}>
                          {formatCurrency(msg.metrics.total)}
                        </p>
                      </div>
                      {msg.metrics.count !== undefined && (
                        <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                          {msg.metrics.count} boleto(s)
                        </span>
                      )}
                    </div>
                  )}

                  {/* Shortcut action button */}
                  {msg.action && !msg.draftBill && (
                    <div style={{ alignSelf: 'flex-start' }}>
                      {msg.action.executeAction === 'mark_paid' && msg.action.billId ? (
                        <button
                          className="btn-primary"
                          onClick={() => handleConfirmPayment(msg.action!.billId!, msg.id)}
                          disabled={executingActionId === msg.id}
                          style={{
                            fontSize: 12,
                            padding: '8px 14px',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 6,
                          }}
                        >
                          <CheckCircle2 size={14} />
                          <span>
                            {executingActionId === msg.id ? 'Baixando...' : msg.action.label}
                          </span>
                        </button>
                      ) : msg.action.route ? (
                        <button
                          className="btn-secondary"
                          onClick={() => navigate(msg.action!.route!)}
                          style={{
                            fontSize: 12,
                            padding: '6px 12px',
                            justifyContent: 'space-between',
                          }}
                        >
                          <span>{msg.action.label}</span>
                          <ArrowRight size={14} style={{ marginLeft: 6 }} />
                        </button>
                      ) : null}
                    </div>
                  )}
                </div>
              </div>
            );
          })}

          {/* Typing / Processing indicator */}
          {loading && (
            <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
              <div
                style={{
                  width: 32,
                  height: 32,
                  borderRadius: 'var(--radius-full)',
                  background: 'var(--brand-dim)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                <Bot size={18} color="var(--brand)" />
              </div>
              <div
                style={{
                  padding: '10px 14px',
                  borderRadius: '4px 16px 16px 16px',
                  background: 'var(--surface)',
                  border: '1px solid var(--border)',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 6,
                }}
              >
                <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                  <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--brand)', animation: 'pulse 1s infinite alternate' }} />
                  <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--brand)', animation: 'pulse 1s 0.2s infinite alternate' }} />
                  <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--brand)', animation: 'pulse 1s 0.4s infinite alternate' }} />
                  <span style={{ fontSize: 11, color: 'var(--text-muted)', marginLeft: 4 }}>
                    {loadingStatus}
                  </span>
                </div>
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Suggested Quick Prompt Chips */}
      <div
        style={{
          flexShrink: 0,
          overflowX: 'auto',
          whiteSpace: 'nowrap',
          padding: '8px 16px',
          borderTop: '1px solid var(--border)',
          background: 'var(--surface)',
        }}
      >
        <div className="container" style={{ display: 'flex', gap: 8, padding: 0 }}>
          {promptSuggestions.map((prompt, i) => (
            <button
              key={i}
              onClick={() => handleSend(prompt)}
              className="btn-ghost"
              style={{
                fontSize: 12,
                padding: '6px 12px',
                borderRadius: 999,
                background: 'var(--surface-2)',
                border: '1px solid var(--border)',
                whiteSpace: 'nowrap',
                flexShrink: 0,
                color: 'var(--text)',
              }}
            >
              {prompt}
            </button>
          ))}
        </div>
      </div>

      {/* Image Preview Chip if attached */}
      {stagedImage && (
        <div
          style={{
            padding: '8px 16px',
            background: 'var(--surface-2)',
            borderTop: '1px solid var(--border)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <img
              src={stagedImage.dataUrl}
              alt="Prévia"
              style={{ width: 36, height: 36, borderRadius: 6, objectFit: 'cover', border: '1px solid var(--border)' }}
            />
            <div>
              <p style={{ fontSize: 12, fontWeight: 600, margin: 0, color: '#fff' }}>
                {stagedImage.file.name}
              </p>
              <span style={{ fontSize: 10, color: 'var(--ok)' }}>
                Pronto para leitura via IA ({OPENAI_CONFIG.model})
              </span>
            </div>
          </div>
          <button
            className="btn-ghost btn-icon"
            onClick={() => setStagedImage(null)}
            style={{ width: 28, height: 28, minHeight: 28 }}
            aria-label="Remover imagem"
          >
            <X size={16} />
          </button>
        </div>
      )}

      {/* Message Input Box */}
      <div
        style={{
          flexShrink: 0,
          padding: '12px 16px',
          background: 'var(--surface)',
          borderTop: '1px solid var(--border)',
        }}
      >
        <div className="container" style={{ padding: 0, display: 'flex', gap: 8, alignItems: 'center' }}>
          {/* Hidden File Input */}
          <input
            type="file"
            ref={fileInputRef}
            accept="image/png,image/jpeg,image/webp,image/jpg"
            style={{ display: 'none' }}
            onChange={handleImagePick}
          />

          {/* Attachment Button */}
          <button
            type="button"
            className="btn-ghost btn-icon"
            onClick={() => fileInputRef.current?.click()}
            disabled={loading}
            aria-label="Anexar imagem de boleto"
            title="Anexar foto ou print de boleto"
            style={{
              width: 44,
              height: 44,
              borderRadius: 'var(--radius-full)',
              flexShrink: 0,
              background: stagedImage ? 'var(--brand-dim)' : 'var(--surface-2)',
              color: stagedImage ? 'var(--brand)' : 'var(--text-muted)',
            }}
          >
            <ImageIcon size={20} />
          </button>

          <input
            type="text"
            className="input"
            placeholder={
              stagedImage
                ? "Adicione uma instrução opcional ou envie para leitura..."
                : "Digite um comando, dúvida ou cole código de barras..."
            }
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter') handleSend();
            }}
            disabled={loading}
            style={{ borderRadius: 'var(--radius-full)' }}
          />

          <button
            className="btn-primary btn-icon"
            onClick={() => handleSend()}
            disabled={(!input.trim() && !stagedImage) || loading}
            aria-label="Enviar mensagem"
            style={{ width: 44, height: 44, borderRadius: 'var(--radius-full)', flexShrink: 0 }}
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </main>
  );
}
