// ── Business Day rule (Regra 7.2) ───────────────────────────
export interface BusinessDayInfo {
  isWeekend: boolean;
  dayOfWeek: number; // 0 = Sunday, 6 = Saturday
  effectiveDueDate: string; // YYYY-MM-DD
  tip?: string;
}

export function getBusinessDayInfo(dueDateStr: string): BusinessDayInfo {
  const date = parseISO(dueDateStr);
  const dayOfWeek = date.getDay();

  if (dayOfWeek === 6) {
    // Saturday -> next Monday
    const monday = new Date(date);
    monday.setDate(monday.getDate() + 2);
    return {
      isWeekend: true,
      dayOfWeek,
      effectiveDueDate: format(monday, 'yyyy-MM-dd'),
      tip: 'Vence no sábado (pagável até 2ª feira sem juros)',
    };
  }

  if (dayOfWeek === 0) {
    // Sunday -> next Monday
    const monday = new Date(date);
    monday.setDate(monday.getDate() + 1);
    return {
      isWeekend: true,
      dayOfWeek,
      effectiveDueDate: format(monday, 'yyyy-MM-dd'),
      tip: 'Vence no domingo (pagável até 2ª feira sem juros)',
    };
  }

  return {
    isWeekend: false,
    dayOfWeek,
    effectiveDueDate: dueDateStr,
  };
}

// ── Due date label ─────────────────────────────────────────
export function getDueDateLabel(dueDate: string, status: string): string {
  if (status === 'paid') return 'Pago';
  if (status === 'canceled') return 'Cancelado';
  const days = daysToDate(dueDate);
  const biz = getBusinessDayInfo(dueDate);

  if (days < 0) {
    if (biz.isWeekend && daysToDate(biz.effectiveDueDate) === 0) {
      return 'Vence hoje (prorrogado do fim de semana)';
    }
    return `Atrasado há ${Math.abs(days)} dia${Math.abs(days) > 1 ? 's' : ''}`;
  }
  if (days === 0) {
    if (biz.isWeekend) return 'Vence hoje · Pague até 2ª feira';
    return 'Vence hoje';
  }
  if (days === 1) {
    if (biz.dayOfWeek === 6) return 'Vence amanhã (sáb) · Pague até 2ª feira';
    return 'Vence amanhã';
  }
  if (biz.isWeekend) {
    return `Vence em ${days} dias (${biz.dayOfWeek === 6 ? 'sábado' : 'domingo'})`;
  }
  return `Vence em ${days} dias`;
}

// ── Barcode validation ──────────────────────────────────────
export function validateBarcodeLine(line: string): boolean {
  const digits = line.replace(/\D/g, '');
  return digits.length === 47 || digits.length === 48;
}

export function parseBarcodeDate(factorStr: string): Date | null {
  const factor = parseInt(factorStr, 10);
  if (!factor || factor === 0) return null;

  // Fator de vencimento: dias desde 07/10/1997.
  // O BACEN atingiu o fator 9999 em ~22/02/2025 e reiniciou em 1000 (gen2).
  // Fatores 1000-9999 são agora ambíguos (gen1 ou gen2).
  const base = new Date('1997-10-07');
  const RESTART_DATE = new Date('2025-02-22'); // Dia do reinício do fator

  if (factor < 1000) {
    // Fatores 0-999 nunca foram usados na gen1 (reservados pelo BACEN).
    // Retorna gen1 como fallback (resultado ficará no passado).
    const result = new Date(base);
    result.setDate(result.getDate() + factor);
    return result;
  }

  // Interpretação gen1: dias = fator (contagem direta desde a base)
  const gen1Date = new Date(base);
  gen1Date.setDate(gen1Date.getDate() + factor);

  // Heurística gen2: se a data gen1 está há mais de 1 ano no passado,
  // reinterpreta como gen2 (fator 1000 = 22/02/2025, 1001 = 23/02/2025...)
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

  if (gen1Date < oneYearAgo) {
    const gen2Date = new Date(RESTART_DATE);
    gen2Date.setDate(gen2Date.getDate() + (factor - 1000));
    return gen2Date;
  }

  return gen1Date;
}

export function formatBarcodeDisplay(line: string): string {
  const d = line.replace(/\D/g, '');
  if (d.length === 47) {
    // Boleto bancário: AAAAA.BBBBB CCCCC.DDDDDD EEEEE.FFFFFF G HHHHHHHHHHHHHHHHH
    return `${d.slice(0,5)}.${d.slice(5,10)} ${d.slice(10,15)}.${d.slice(15,21)} ${d.slice(21,26)}.${d.slice(26,32)} ${d.slice(32,33)} ${d.slice(33)}`;
  }
  if (d.length === 48) {
    return `${d.slice(0, 11)}-${d.slice(11, 12)} ${d.slice(12, 23)}-${d.slice(23, 24)} ${d.slice(24, 35)}-${d.slice(35, 36)} ${d.slice(36, 47)}-${d.slice(47, 48)}`;
  }
  return line;
}

export interface ExtractedBoletoInfo {
  barcodeLine: string;
  formattedLine: string;
  amount: number | null;
  dueDate: string | null;
  bankName?: string;
}

export function extractBoletoData(rawLine: string): ExtractedBoletoInfo | null {
  const digits = rawLine.replace(/\D/g, '');
  if (digits.length !== 47 && digits.length !== 48) return null;

  if (digits.length === 47) {
    const factorStr = digits.slice(33, 37);
    const valueStr = digits.slice(37, 47);
    const parsedDate = parseBarcodeDate(factorStr);
    const dueDate = parsedDate ? format(parsedDate, 'yyyy-MM-dd') : null;
    const centavos = parseInt(valueStr, 10);
    const amount = isNaN(centavos) || centavos === 0 ? null : centavos / 100;

    const bankCode = digits.slice(0, 3);
    const banks: Record<string, string> = {
      '001': 'Banco do Brasil',
      '033': 'Santander',
      '104': 'Caixa Econômica Federal',
      '237': 'Bradesco',
      '341': 'Itaú Unibanco',
      '748': 'Sicredi',
      '756': 'Sicoob',
      '260': 'Nubank',
      '077': 'Banco Inter',
    };
    const bankName = banks[bankCode] || `Banco ${bankCode}`;

    return {
      barcodeLine: digits,
      formattedLine: formatBarcodeDisplay(digits),
      amount,
      dueDate,
      bankName,
    };
  }

  return {
    barcodeLine: digits,
    formattedLine: formatBarcodeDisplay(digits),
    amount: null,
    dueDate: null,
    bankName: 'Concessionária / Tributo',
  };
}

/**
 * Gera uma linha digitável (47 dígitos) sinteticamente válida para simulações e demos.
 * Usa fator gen2 do BACEN (reinício em 22/02/2025), então `parseBarcodeDate()` resolve
 * a data corretamente para qualquer `daysFromNow` futuro.
 *
 * @param daysFromNow  Dias a partir de hoje para o vencimento
 * @param amountCents  Valor em centavos (ex: 345000 = R$3.450,00)
 * @param bankPrefix   Código do banco, 3 dígitos (padrão: '341' = Itaú)
 */
export function generateDemoBoleto(
  daysFromNow: number,
  amountCents: number,
  bankPrefix = '341'
): string {
  // Fator gen2: fator 1000 = 22/02/2025, 1001 = 23/02/2025, etc.
  const RESTART_DATE = new Date('2025-02-22');
  const targetDate = new Date(Date.now() + daysFromNow * 86400000);
  const daysFromRestart = Math.max(
    0,
    Math.ceil((targetDate.getTime() - RESTART_DATE.getTime()) / 86400000)
  );
  const factor = String(1000 + daysFromRestart).padStart(4, '0');
  const value = String(Math.round(amountCents)).padStart(10, '0');
  // Primeiros 33 dígitos: prefixo do banco + campos livres (não lidos pelo extrator)
  const freeField = `${bankPrefix}917900101043510047910201500849`;
  return `${freeField}${factor}${value}`; // 33 + 4 + 10 = 47 dígitos
}

// ── Group bills by due date ─────────────────────────────────
export interface BillGroup {
  label: string;
  date: string;
  bills: BillView[];
}

export function groupBillsByDate(bills: BillView[]): BillGroup[] {
  const map = new Map<string, BillView[]>();
  for (const bill of bills) {
    const key = bill.due_date;
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(bill);
  }
  return Array.from(map.entries()).map(([date, bills]) => ({
    label: formatDate(date),
    date,
    bills,
  }));
}

// ── Interest paid ────────────────────────────────────────────
export function calcInterestPaid(amount: number, paidAmount: number | null): number {
  if (!paidAmount || paidAmount <= amount) return 0;
  return paidAmount - amount;
}

// ── Detect platform ──────────────────────────────────────────
export function getPlatform(): 'ios' | 'android' | 'web' {
  const ua = navigator.userAgent;
  if (/iPad|iPhone|iPod/.test(ua)) return 'ios';
  if (/Android/.test(ua)) return 'android';
  return 'web';
}

export function isStandalone(): boolean {
  if (typeof window === 'undefined') return false;
  return (
    window.matchMedia('(display-mode: standalone)').matches ||
    window.matchMedia('(display-mode: fullscreen)').matches ||
    window.matchMedia('(display-mode: minimal-ui)').matches ||
    (window.navigator as any).standalone === true ||
    document.referrer.includes('android-app://')
  );
}
