/**
 * Cliente OpenAI para o Assistente Inteligente Cronos (Morpheus Relojoaria)
 * Suporta modelo gpt-5.4-mini e visão computacional para leitura de boletos.
 */

import { supabase } from './supabase';

/**
 * Obtém a chave da OpenAI de forma segura:
 * 1. Primeiro verifica se o usuário configurou uma chave em Configurações (armazenada apenas no localStorage do navegador)
 * 2. Em seguida, verifica variável de ambiente local (dev) se fornecida
 * 3. NUNCA utiliza chaves hardcoded no código para evitar vazamento em bundles públicos
 */
export function getOpenAiApiKey(): string {
  try {
    const localKey = localStorage.getItem('cronos_openai_api_key');
    if (localKey && localKey.trim().startsWith('sk-')) {
      return localKey.trim();
    }
  } catch (e) {
    // LocalStorage indisponível
  }

  const envKey = (import.meta.env.VITE_OPENAI_API_KEY as string) || '';
  if (envKey && envKey.trim().startsWith('sk-')) {
    return envKey.trim();
  }

  return '';
}

export function setOpenAiApiKey(key: string): void {
  try {
    if (key.trim()) {
      localStorage.setItem('cronos_openai_api_key', key.trim());
    } else {
      localStorage.removeItem('cronos_openai_api_key');
    }
  } catch (e) {
    console.warn('Erro ao salvar chave no localStorage:', e);
  }
}

export function hasOpenAiApiKey(): boolean {
  return getOpenAiApiKey().length > 0;
}

export const OPENAI_CONFIG = {
  get apiKey() {
    return getOpenAiApiKey();
  },
  model: (import.meta.env.VITE_OPENAI_MODEL as string) || 'gpt-5.4-mini',
  endpoint: 'https://api.openai.com/v1/chat/completions',
};

export interface ExtractedBoletoAi {
  beneficiary_name: string;
  amount: number | null;
  due_date: string | null; // YYYY-MM-DD
  barcode_line: string | null;
  description?: string;
  confidence: number;
  notes?: string;
  suggested_category?: string;
}

export interface FinancialContext {
  orgName: string;
  totalPending: number;
  totalOverdue: number;
  overdueCount: number;
  dueTodayCount: number;
  dueWeekCount: number;
  currentMonthPending: number;
  currentMonthPaid: number;
  topOverdueBills: Array<{ beneficiary: string; amount: number; due_date: string }>;
  topUpcomingBills: Array<{ beneficiary: string; amount: number; due_date: string }>;
  suppliersList: string[];
  categoriesList: string[];
}

/**
 * Chama a API da OpenAI para responder dúvidas e análises financeiras usando gpt-5.4-mini
 */
export async function askFinancialAI(
  conversationHistory: Array<{ role: 'user' | 'assistant'; content: string }>,
  currentPrompt: string,
  context: FinancialContext
): Promise<{ text: string; tokensUsed: number; model: string }> {
  const systemPrompt = `Você é o Assistente Financeiro Inteligente do Cronos (sistema de gestão de boletos da Morpheus Relojoaria).
Sua missão é ajudar o gestor financeiro com precisão, clareza e autoridade no controle de contas a pagar e fluxo de caixa.

DADOS EM TEMPO REAL DA EMPRESA (${context.orgName}):
- Total pendente geral: R$ ${context.totalPending.toFixed(2)}
- Boletos atrasados: ${context.overdueCount} (Total: R$ ${context.totalOverdue.toFixed(2)})
- Boletos vencendo hoje: ${context.dueTodayCount}
- Boletos vencendo nos próximos 7 dias: ${context.dueWeekCount}
- Mês atual - a pagar: R$ ${context.currentMonthPending.toFixed(2)} | já pago: R$ ${context.currentMonthPaid.toFixed(2)}
- Fornecedores cadastrados: ${context.suppliersList.join(', ') || 'Nenhum cadastrado'}
- Categorias: ${context.categoriesList.join(', ') || 'Geral'}

PRINCIPAIS ATRASADOS:
${context.topOverdueBills.length > 0 ? context.topOverdueBills.map(b => `• ${b.beneficiary}: R$ ${b.amount.toFixed(2)} (venceu ${b.due_date})`).join('\n') : 'Nenhum boleto em atraso.'}

PRÓXIMOS VENCIMENTOS:
${context.topUpcomingBills.length > 0 ? context.topUpcomingBills.map(b => `• ${b.beneficiary}: R$ ${b.amount.toFixed(2)} (${b.due_date})`).join('\n') : 'Nenhum próximo vencimento.'}

DIRETRIZES DE RESPOSTA:
1. Seja direto, cordial e focado no financeiro empresarial (relojoaria/joalheria de luxo).
2. Use formatação limpa em Markdown quando listas ou tabelas facilitarem a visualização.
3. Se perguntarem estratégias, priorize o não pagamento de juros/multas e quitação com grandes fornecedores de relógios.
4. Responda em Português do Brasil.`;

  // Construir mensagens com histórico recente (últimas 6 mensagens para economia de contexto)
  const recentHistory = conversationHistory.slice(-6).map(m => ({
    role: m.role,
    content: m.content,
  }));

  const messages = [
    { role: 'system', content: systemPrompt },
    ...recentHistory,
    { role: 'user', content: currentPrompt },
  ];

  const apiKey = OPENAI_CONFIG.apiKey;

  // Se o usuário não configurou chave no cliente, tenta invocar a Edge Function segura do Supabase
  if (!apiKey) {
    try {
      const { data, error } = await supabase.functions.invoke('ai-assistant', {
        body: {
          action: 'chat',
          messages,
          model: OPENAI_CONFIG.model,
        },
      });

      if (!error && data?.text) {
        return {
          text: data.text,
          tokensUsed: data.tokensUsed || 0,
          model: data.model || OPENAI_CONFIG.model,
        };
      }

      if (data?.error) {
        throw new Error(data.error);
      }
      if (error && error.message && !error.message.includes('404') && !error.message.includes('Failed to send a request')) {
        throw new Error(`Erro no assistente Supabase: ${error.message}`);
      }
    } catch (edgeErr: any) {
      if (edgeErr?.message && !edgeErr.message.includes('não configurada')) {
        throw edgeErr;
      }
      console.warn('Edge function ai-assistant indisponível:', edgeErr);
    }

    throw new Error(
      'Chave da OpenAI não configurada. Para usar respostas inteligentes com gpt-5.4-mini, adicione sua API Key em Configurações > Inteligência Artificial ou publique a Edge Function no Supabase.'
    );
  }

  const response = await fetch(OPENAI_CONFIG.endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: OPENAI_CONFIG.model,
      messages,
      max_completion_tokens: 800,
    }),
  });

  if (!response.ok) {
    const errorBody = await response.text();
    console.error('OpenAI API Error:', errorBody);
    throw new Error(`Erro OpenAI (${response.status}): ${response.statusText}`);
  }

  const data = await response.json();
  const choice = data.choices?.[0];
  const text = choice?.message?.content || 'Não foi possível gerar a resposta.';
  const tokensUsed = data.usage?.total_tokens || 0;

  return {
    text,
    tokensUsed,
    model: data.model || OPENAI_CONFIG.model,
  };
}

/**
 * Função utilitária para extrair e normalizar JSON de resposta de visão computacional
 */
function parseBoletoVisionJson(rawText: string, tokensUsed: number): {
  boleto: ExtractedBoletoAi;
  rawExplanation: string;
  tokensUsed: number;
} {
  const cleaned = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsedJson: Partial<ExtractedBoletoAi> = {};
  try {
    parsedJson = JSON.parse(cleaned);
  } catch {
    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        parsedJson = JSON.parse(jsonMatch[0]);
      } catch (e) {
        console.warn('Falha no JSON parse secundário:', e);
      }
    }
  }

  const boleto: ExtractedBoletoAi = {
    beneficiary_name: parsedJson.beneficiary_name || 'Boleto Identificado por IA',
    amount: typeof parsedJson.amount === 'number' ? parsedJson.amount : null,
    due_date: parsedJson.due_date || null,
    barcode_line: parsedJson.barcode_line ? String(parsedJson.barcode_line).replace(/\D/g, '') : null,
    description: parsedJson.description || 'Boleto extraído via imagem pelo gpt-5.4-mini',
    confidence: typeof parsedJson.confidence === 'number' ? parsedJson.confidence : 90,
    suggested_category: parsedJson.suggested_category || 'Mercadorias',
  };

  return {
    boleto,
    rawExplanation: rawText,
    tokensUsed,
  };
}

/**
 * Extrai dados estruturados de boletos a partir de imagem (foto, scanner ou print) usando visão de gpt-5.4-mini
 */
export async function extractBoletoFromImageAi(
  dataUrlOrBase64: string,
  userInstruction?: string
): Promise<{ boleto: ExtractedBoletoAi; rawExplanation: string; tokensUsed: number }> {
  const imageUrl = dataUrlOrBase64.startsWith('data:')
    ? dataUrlOrBase64
    : `data:image/jpeg;base64,${dataUrlOrBase64}`;

  const promptText = `Você é um leitor óptico especialista em boletos bancários brasileiros e contas de consumo (energia, água, telecomunicações, fornecedores de relógios como Casio, Seiko, Citizen).
Analise com extrema precisão esta imagem do boleto/documento financeiro.

${userInstruction ? `Instrução adicional do usuário: "${userInstruction}"` : ''}

Extraia os seguintes campos OBRIGATORIAMENTE em formato JSON estrito:
{
  "beneficiary_name": "Nome da empresa/cedente/fornecedor (ex: Casio Brasil, Copel, Vivo, Seiko)",
  "amount": 0.00, // número decimal float, sem R$ e sem separador de milhar. null se ilegível
  "due_date": "YYYY-MM-DD", // data de vencimento no padrão ISO YYYY-MM-DD. null se ilegível
  "barcode_line": "34191...", // Apenas dígitos (47 ou 48 números) da linha digitável se visível, ou null se não encontrada
  "description": "Breve resumo do documento (ex: Fatura de energia elétrica, Fornecimento de peças)",
  "confidence": 95, // Grau de confiança de 0 a 100
  "suggested_category": "Mercadorias" // ou "Infraestrutura", "Impostos", "Serviços", "Geral"
}

Responda APENAS com o objeto JSON válido, sem texto introdutório ou markdown extra se possível.`;

  const apiKey = OPENAI_CONFIG.apiKey;

  if (!apiKey) {
    try {
      const { data, error } = await supabase.functions.invoke('ai-assistant', {
        body: {
          action: 'vision',
          imageUrl,
          promptText,
          model: OPENAI_CONFIG.model,
        },
      });

      if (!error && data?.rawText) {
        return parseBoletoVisionJson(data.rawText, data.tokensUsed || 0);
      }

      if (data?.error) {
        throw new Error(data.error);
      }
      if (error && error.message && !error.message.includes('404') && !error.message.includes('Failed to send a request')) {
        throw new Error(`Erro na visão computacional Supabase: ${error.message}`);
      }
    } catch (edgeErr: any) {
      if (edgeErr?.message && !edgeErr.message.includes('não configurada')) {
        throw edgeErr;
      }
      console.warn('Edge function ai-assistant vision indisponível:', edgeErr);
    }

    throw new Error(
      'Chave da OpenAI não configurada. Configure sua API Key em Configurações > Inteligência Artificial ou publique a Edge Function no Supabase.'
    );
  }

  const response = await fetch(OPENAI_CONFIG.endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: OPENAI_CONFIG.model,
      messages: [
        {
          role: 'user',
          content: [
            { type: 'text', text: promptText },
            { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
          ],
        },
      ],
      max_completion_tokens: 1000,
    }),
  });

  if (!response.ok) {
    const errorBody = await response.text();
    console.error('OpenAI Vision Error:', errorBody);
    throw new Error(`Erro OpenAI Vision (${response.status}): ${response.statusText}`);
  }

  const data = await response.json();
  const rawText = data.choices?.[0]?.message?.content || '{}';
  const tokensUsed = data.usage?.total_tokens || 0;

  return parseBoletoVisionJson(rawText, tokensUsed);
}
