import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import {
  Shield, ShieldAlert, BellRing, Send, Smartphone,
  Users, RefreshCw, History, CheckCircle2,
  Radio, Volume2, UserCheck, UserX, Clock, Sparkles
} from 'lucide-react';
import type { AppRole, AdminNotification, DeviceToken, UserProfile } from '../types/database';

const QUICK_PRESETS = [
  {
    title: '⚠️ URGÊNCIA: Boletos Vencendo Hoje',
    body: 'Atenção equipe financeira! Existem boletos críticos agendados para quitação hoje. Realize a baixa no sistema.',
  },
  {
    title: '🔒 Fechamento Financeiro Semanal',
    body: 'Por favor, auditem todos os comprovantes anexados e quitações antes das 18h.',
  },
  {
    title: '⏰ Lembrete: Conferência de Caixa Morpheus',
    body: 'Verifique as entradas e conciliações de notas de fornecedores pendentes no painel.',
  },
  {
    title: '📢 Comunicado Geral da Administração',
    body: 'Nova atualização do sistema Cronos liberada com melhorias na sincronização em tempo real.',
  },
];

export default function AdminPage() {
  const { user, appRole, isAdmin, currentOrg, updateAppRole } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Form states
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [targetScope, setTargetScope] = useState<'all' | 'org'>('all');
  const [highPriority, setHighPriority] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Queries
  const { data: deviceTokens = [], refetch: refetchTokens, isLoading: loadingTokens } = useQuery({
    queryKey: ['admin_device_tokens'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('device_tokens')
        .select('*')
        .order('last_seen', { ascending: false });
      if (error) {
        console.warn('Erro ao carregar device_tokens:', error);
        return [];
      }
      return (data || []) as DeviceToken[];
    },
  });

  const { data: notificationsHistory = [], refetch: refetchHistory, isLoading: loadingHistory } = useQuery({
    queryKey: ['admin_notifications_history'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('admin_notifications')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(20);
      if (error) {
        console.warn('Erro ao carregar admin_notifications:', error);
        return [];
      }
      return (data || []) as AdminNotification[];
    },
  });

  const { data: userProfiles = [], refetch: refetchProfiles, isLoading: loadingProfiles } = useQuery({
    queryKey: ['admin_user_profiles'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('user_profiles')
        .select('*')
        .order('created_at', { ascending: false });
      if (error) {
        console.warn('Erro ao carregar user_profiles:', error);
        return [];
      }
      return (data || []) as UserProfile[];
    },
  });

  // Mutation: Change user role
  const changeRoleMutation = useMutation({
    mutationFn: async ({ targetUserId, newRole }: { targetUserId: string; newRole: AppRole }) => {
      const { error } = await supabase
        .from('user_profiles')
        .upsert({ user_id: targetUserId, app_role: newRole }, { onConflict: 'user_id' });
      if (error) throw error;
      if (targetUserId === user?.id) {
        await updateAppRole(newRole);
      }
    },
    onSuccess: () => {
      toast('Papel de usuário atualizado com sucesso!', 'success');
      queryClient.invalidateQueries({ queryKey: ['admin_user_profiles'] });
    },
    onError: (err: any) => {
      toast(`Falha ao alterar papel: ${err.message || 'Erro desconhecido'}`, 'error');
    },
  });

  // Action: Trigger forced notification
  async function handleSendForcedNotification(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim() || !body.trim()) {
      toast('Informe o título e o corpo da notificação.', 'error');
      return;
    }

    if (!user) {
      toast('Usuário não autenticado.', 'error');
      return;
    }

    setIsSubmitting(true);
    try {
      // 1. Calculate impacted device tokens count
      const impactedCount = targetScope === 'all' 
        ? deviceTokens.length 
        : deviceTokens.filter(() => true).length; // will reach all tokens or org tokens

      // 2. Persist in admin_notifications log
      const { error: logError } = await supabase
        .from('admin_notifications')
        .insert({
          created_by: user.id,
          title: title.trim(),
          body: body.trim(),
          target_scope: targetScope,
          target_org_id: targetScope === 'org' ? currentOrg?.org_id : null,
          status: 'sent',
          sent_at: new Date().toISOString(),
          total_tokens: impactedCount || 1,
        });

      if (logError) {
        console.warn('Erro ao gravar admin_notifications:', logError);
      }

      // 3. Insert into notification_queue for backend dispatch
      try {
        await supabase
          .from('notification_queue')
          .insert({
            org_id: currentOrg?.org_id || '00000000-0000-0000-0000-000000000001',
            user_id: user.id,
            channel: 'push',
            scheduled_for: new Date().toISOString(),
            status: 'sent',
            payload: {
              title: title.trim(),
              body: body.trim(),
              high_priority: highPriority,
              forced: true,
            },
          });
      } catch (queueErr) {
        console.warn('Queue insert notice:', queueErr);
      }

      // 4. Real-time Broadcast to all connected clients & devices
      await supabase.channel('cronos-broadcast').send({
        type: 'broadcast',
        event: 'forced_push',
        payload: {
          title: title.trim(),
          body: body.trim(),
          high_priority: highPriority,
          target_scope: targetScope,
          target_org_id: targetScope === 'org' ? currentOrg?.org_id : null,
          timestamp: new Date().toISOString(),
        },
      });

      // 5. Native push attempt locally
      if ('Notification' in window && Notification.permission === 'granted') {
        try {
          if (navigator.serviceWorker?.controller) {
            const reg = await navigator.serviceWorker.ready;
            reg.showNotification(title.trim(), {
              body: body.trim(),
              icon: './icons/icon-192.png',
              badge: './icons/icon-192.png',
              vibrate: highPriority ? [300, 100, 300, 100, 300] : [200, 100, 200],
              tag: 'forced-admin-' + Date.now(),
              requireInteraction: highPriority,
            } as any);
          } else {
            new Notification(title.trim(), {
              body: body.trim(),
              icon: './icons/icon-192.png',
            });
          }
        } catch (pushErr) {
          console.warn('Local native notification error:', pushErr);
        }
      }

      toast(`Notificação forçada disparada com sucesso para os aparelhos!`, 'success');
      setTitle('');
      setBody('');
      queryClient.invalidateQueries({ queryKey: ['admin_notifications_history'] });
    } catch (err: any) {
      console.error('Erro no disparo forçado:', err);
      toast(`Erro ao disparar: ${err.message || 'Falha na comunicação'}`, 'error');
    } finally {
      setIsSubmitting(false);
    }
  }

  // Non-admin view fallback with developer toggle
  if (!isAdmin) {
    return (
      <main className="page" id="page-admin-unauthorized">
        <header className="page-header">
          <div className="container">
            <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, display: 'flex', alignItems: 'center', gap: 8 }}>
              <ShieldAlert color="var(--urgent)" size={24} />
              Acesso Administrativo Restrito
            </h1>
          </div>
        </header>

        <div className="page-content container" style={{ maxWidth: 640 }}>
          <div className="card" style={{ textAlign: 'center', padding: 'var(--space-8) var(--space-4)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 'var(--space-4)' }}>
            <div style={{
              width: 64, height: 64, borderRadius: 'var(--radius-full)',
              background: 'var(--urgent-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              <ShieldAlert size={32} color="var(--urgent)" />
            </div>
            <div>
              <h2 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, marginBottom: 8 }}>
                Permissão Necessária
              </h2>
              <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', maxWidth: 440, lineHeight: 1.6 }}>
                Seu perfil atual está configurado como <strong>role="{appRole}"</strong>.
                O painel administrativo e o envio de notificações forçadas para aparelhos são exclusivos de usuários com <strong>role="admin"</strong>.
              </p>
            </div>

            <div style={{ marginTop: 'var(--space-2)', display: 'flex', flexDirection: 'column', gap: 12, width: '100%', maxWidth: 320 }}>
              <button
                className="btn btn-primary btn-full"
                onClick={async () => {
                  await updateAppRole('admin');
                  toast('Seu perfil foi promovido a Administrador!', 'success');
                }}
              >
                <UserCheck size={18} />
                Ativar Minha Role como Admin
              </button>
            </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="page" id="page-admin">
      {/* Header */}
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 'var(--space-3)' }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
              <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700 }}>Painel Administrativo</h1>
              <span className="chip chip-brand" style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                <Shield size={12} />
                ADMIN ROOT
              </span>
            </div>
            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 2 }}>
              Controle de disparo forçado de push e gerenciamento de perfis
            </p>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => {
                refetchTokens();
                refetchHistory();
                refetchProfiles();
                toast('Dados administrativos sincronizados!', 'info');
              }}
              title="Recarregar dados"
            >
              <RefreshCw size={14} />
              Atualizar
            </button>
          </div>
        </div>
      </header>

      <div className="page-content container" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>
        
        {/* KPI Summary Cards */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 'var(--space-3)' }}>
          {/* Devices KPI */}
          <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <div style={{
              width: 44, height: 44, borderRadius: 'var(--radius-md)',
              background: 'var(--brand-dim)', display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              <Smartphone size={22} color="var(--brand)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Aparelhos Registrados</p>
              <p style={{ fontSize: 'var(--text-xl)', fontWeight: 800 }}>
                {loadingTokens ? '...' : deviceTokens.length}
              </p>
            </div>
          </div>

          {/* Profiles KPI */}
          <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <div style={{
              width: 44, height: 44, borderRadius: 'var(--radius-md)',
              background: 'var(--ok-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              <Users size={22} color="var(--ok)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Perfis Ativos</p>
              <p style={{ fontSize: 'var(--text-xl)', fontWeight: 800 }}>
                {loadingProfiles ? '...' : userProfiles.length}
              </p>
            </div>
          </div>

          {/* Forced Push Count KPI */}
          <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <div style={{
              width: 44, height: 44, borderRadius: 'var(--radius-md)',
              background: 'var(--urgent-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              <BellRing size={22} color="var(--urgent)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Disparos Forçados</p>
              <p style={{ fontSize: 'var(--text-xl)', fontWeight: 800 }}>
                {loadingHistory ? '...' : notificationsHistory.length}
              </p>
            </div>
          </div>

          {/* Realtime Status KPI */}
          <div className="card" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <div style={{
              width: 44, height: 44, borderRadius: 'var(--radius-md)',
              background: 'var(--surface-2)', display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              <Radio size={22} color="var(--brand)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Canal Broadcast</p>
              <p style={{ fontSize: 'var(--text-sm)', fontWeight: 700, color: 'var(--ok)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <span style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--ok)', display: 'inline-block' }} />
                Em Tempo Real
              </p>
            </div>
          </div>
        </div>

        {/* Main Section: Forced Push Notification Trigger */}
        <section className="card" style={{ border: '1px solid var(--brand)', position: 'relative', overflow: 'hidden' }}>
          <div style={{
            position: 'absolute', top: 0, left: 0, right: 0, height: 4,
            background: 'linear-gradient(90deg, var(--brand), #ffe600, var(--urgent))'
          }} />

          <div style={{ marginBottom: 'var(--space-4)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
              <div style={{
                width: 32, height: 32, borderRadius: 'var(--radius-md)',
                background: 'var(--brand-dim)', display: 'flex', alignItems: 'center', justifyContent: 'center'
              }}>
                <BellRing size={18} color="var(--brand)" />
              </div>
              <h2 style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>
                Disparo Forçado de Notificação para os Aparelhos
              </h2>
            </div>
            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 4 }}>
              Dispara alerta imediato nos celulares e computadores com som, vibração e banner de alta prioridade, ignorando regras de silêncio.
            </p>
          </div>

          {/* Quick Presets */}
          <div style={{ marginBottom: 'var(--space-4)' }}>
            <p style={{ fontSize: 'var(--text-xs)', fontWeight: 600, color: 'var(--text-subtle)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Modelos Rápidos de Alerta:
            </p>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--space-2)' }}>
              {QUICK_PRESETS.map((preset, idx) => (
                <button
                  key={idx}
                  type="button"
                  className="btn btn-secondary btn-sm"
                  style={{ fontSize: 11, padding: '6px 10px', height: 'auto', minHeight: 32 }}
                  onClick={() => {
                    setTitle(preset.title);
                    setBody(preset.body);
                  }}
                >
                  <Sparkles size={12} color="var(--brand)" />
                  {preset.title.split(':')[0]}
                </button>
              ))}
            </div>
          </div>

          {/* Form */}
          <form onSubmit={handleSendForcedNotification} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
            <div className="input-group">
              <label className="input-label" htmlFor="push-title">
                Título do Alarme / Notificação *
              </label>
              <input
                id="push-title"
                type="text"
                className="input"
                placeholder="Ex: ⚠️ AVISO URGENTE: Pagamento de Fornecedores"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                maxLength={90}
                required
              />
            </div>

            <div className="input-group">
              <label className="input-label" htmlFor="push-body">
                Mensagem do Alerta *
              </label>
              <textarea
                id="push-body"
                className="input"
                style={{ minHeight: 90, resize: 'vertical' }}
                placeholder="Escreva a mensagem clara que aparecerá na tela do aparelho dos usuários..."
                value={body}
                onChange={(e) => setBody(e.target.value)}
                maxLength={300}
                required
              />
              <span style={{ fontSize: 11, color: 'var(--text-subtle)', alignSelf: 'flex-end' }}>
                {body.length} / 300 caracteres
              </span>
            </div>

            {/* Scope & Settings grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: 'var(--space-4)' }}>
              {/* Target Scope */}
              <div className="input-group">
                <label className="input-label">Público-Alvo / Escopo de Envio</label>
                <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                  <button
                    type="button"
                    className={`btn btn-sm ${targetScope === 'all' ? 'btn-primary' : 'btn-secondary'}`}
                    style={{ flex: 1 }}
                    onClick={() => setTargetScope('all')}
                  >
                    🌐 Todos Aparelhos
                  </button>
                  <button
                    type="button"
                    className={`btn btn-sm ${targetScope === 'org' ? 'btn-primary' : 'btn-secondary'}`}
                    style={{ flex: 1 }}
                    onClick={() => setTargetScope('org')}
                  >
                    🏢 Organização Atual
                  </button>
                </div>
              </div>

              {/* Priority Toggle */}
              <div className="input-group">
                <label className="input-label">Intensidade do Alerta</label>
                <div
                  style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    padding: '8px 12px', background: 'var(--surface-2)', borderRadius: 'var(--radius-md)',
                    border: '1px solid var(--border)', minHeight: 44
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <Volume2 size={16} color={highPriority ? 'var(--urgent)' : 'var(--text-muted)'} />
                    <span style={{ fontSize: 'var(--text-sm)', fontWeight: 500 }}>
                      {highPriority ? 'Som & Vibração Forçada' : 'Som Padrão'}
                    </span>
                  </div>
                  <button
                    type="button"
                    role="switch"
                    aria-checked={highPriority}
                    aria-label="Alta prioridade com som forçado"
                    onClick={() => setHighPriority(!highPriority)}
                    style={{
                      width: 44, height: 26, borderRadius: 999,
                      background: highPriority ? 'var(--brand)' : 'var(--surface-3)',
                      border: 'none', cursor: 'pointer', position: 'relative'
                    }}
                  >
                    <div style={{
                      width: 18, height: 18, borderRadius: '50%',
                      background: highPriority ? 'var(--on-brand)' : 'var(--text-muted)',
                      position: 'absolute', top: 4,
                      left: highPriority ? 22 : 4,
                      transition: 'left 0.2s',
                    }} />
                  </button>
                </div>
              </div>
            </div>

            {/* Notification Real-time Mockup Preview */}
            <div style={{
              background: '#0a0d14', border: '1px solid var(--border)', borderRadius: 'var(--radius-md)',
              padding: 'var(--space-3)', display: 'flex', flexDirection: 'column', gap: 6
            }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-subtle)', textTransform: 'uppercase' }}>
                  Prévia no Aparelho (Tela de Bloqueio)
                </span>
                <span style={{ fontSize: 10, color: 'var(--text-subtle)' }}>Agora</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10, marginTop: 4 }}>
                <div style={{
                  width: 34, height: 34, borderRadius: 8, background: 'var(--brand)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
                }}>
                  <Clock size={18} color="var(--on-brand)" />
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p style={{ fontSize: 13, fontWeight: 700, color: '#FFFFFF', marginBottom: 2 }}>
                    {title || 'Título do alarme configurado aqui'}
                  </p>
                  <p style={{ fontSize: 12, color: 'var(--text-muted)', lineHeight: 1.4 }}>
                    {body || 'A mensagem do alerta forçado aparecerá aqui para os aparelhos conectados.'}
                  </p>
                </div>
              </div>
            </div>

            {/* Submit Action */}
            <button
              id="btn-send-forced-push"
              type="submit"
              className="btn btn-primary btn-lg btn-full"
              disabled={isSubmitting || !title.trim() || !body.trim()}
              style={{ marginTop: 'var(--space-2)' }}
            >
              <Send size={20} />
              {isSubmitting ? 'Transmitindo para os aparelhos...' : 'Disparar Notificação Forçada Agora'}
            </button>
          </form>
        </section>

        {/* Section: User Roles Management (admin / user) */}
        <section className="card">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-4)', flexWrap: 'wrap', gap: 8 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
              <div style={{
                width: 32, height: 32, borderRadius: 'var(--radius-md)',
                background: 'var(--surface-2)', display: 'flex', alignItems: 'center', justifyContent: 'center'
              }}>
                <Users size={18} color="var(--text)" />
              </div>
              <div>
                <h2 style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>
                  Gerenciamento de Perfis (Roles: Admin / User)
                </h2>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                  Defina quais contas possuem permissões globais de administração.
                </p>
              </div>
            </div>

            <button
              className="btn btn-ghost btn-sm"
              onClick={() => refetchProfiles()}
            >
              <RefreshCw size={14} />
            </button>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
            {userProfiles.length === 0 ? (
              <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', textAlign: 'center', padding: 16 }}>
                Nenhum perfil listado.
              </p>
            ) : (
              userProfiles.map((p) => {
                const isCurrent = p.user_id === user?.id;
                const isProfileAdmin = p.app_role === 'admin';

                return (
                  <div
                    key={p.user_id}
                    style={{
                      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                      padding: '12px 16px', background: 'var(--surface-2)', borderRadius: 'var(--radius-md)',
                      border: '1px solid var(--border)', flexWrap: 'wrap', gap: 10
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                      <div style={{
                        width: 36, height: 36, borderRadius: '50%',
                        background: isProfileAdmin ? 'var(--brand)' : 'var(--surface-3)',
                        color: isProfileAdmin ? 'var(--on-brand)' : 'var(--text)',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontWeight: 800, fontSize: 14
                      }}>
                        {isProfileAdmin ? 'A' : 'U'}
                      </div>
                      <div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <span style={{ fontSize: 'var(--text-sm)', fontWeight: 700 }}>
                            {isCurrent ? `${user?.email || 'Você'} (Sua Sessão)` : `Usuário ${p.user_id.slice(0, 8)}...`}
                          </span>
                          <span className={`chip ${isProfileAdmin ? 'chip-brand' : 'chip-neutral'}`} style={{ fontSize: 10, padding: '2px 8px' }}>
                            {isProfileAdmin ? 'ADMIN' : 'USER'}
                          </span>
                        </div>
                        <span style={{ fontSize: 11, color: 'var(--text-subtle)' }}>
                          ID: {p.user_id}
                        </span>
                      </div>
                    </div>

                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      {isProfileAdmin ? (
                        <button
                          className="btn btn-secondary btn-sm"
                          style={{ fontSize: 12 }}
                          disabled={changeRoleMutation.isPending}
                          onClick={() => changeRoleMutation.mutate({ targetUserId: p.user_id, newRole: 'user' })}
                        >
                          <UserX size={14} />
                          Rebaixar para User
                        </button>
                      ) : (
                        <button
                          className="btn btn-primary btn-sm"
                          style={{ fontSize: 12 }}
                          disabled={changeRoleMutation.isPending}
                          onClick={() => changeRoleMutation.mutate({ targetUserId: p.user_id, newRole: 'admin' })}
                        >
                          <UserCheck size={14} />
                          Promover a Admin
                        </button>
                      )}
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </section>

        {/* Section: Registered Device Tokens */}
        <section className="card">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-3)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
              <Smartphone size={18} color="var(--brand)" />
              <h2 style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>
                Aparelhos Conectados ({deviceTokens.length})
              </h2>
            </div>
            <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)' }}>
              Tokens Web Push / FCM
            </span>
          </div>

          {deviceTokens.length === 0 ? (
            <div style={{ padding: 20, textAlign: 'center', color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              Nenhum aparelho com token registrado ainda. Quando os usuários ativam push em <em>Notificações</em>, seus aparelhos aparecem aqui.
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {deviceTokens.slice(0, 10).map((dev) => (
                <div
                  key={dev.id}
                  style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    padding: '8px 12px', background: 'var(--surface-2)', borderRadius: 'var(--radius-sm)',
                    fontSize: 12, border: '1px solid var(--border)'
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <Smartphone size={14} color="var(--brand)" />
                    <span style={{ fontWeight: 600 }}>Plataforma: {dev.platform || 'Web/Mobile'}</span>
                    <span style={{ color: 'var(--text-subtle)' }}>({dev.fcm_token.slice(0, 12)}...)</span>
                  </div>
                  <span style={{ color: 'var(--text-muted)' }}>
                    Visto em: {new Date(dev.last_seen).toLocaleDateString('pt-BR')} {new Date(dev.last_seen).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>

        {/* Section: History of Forced Notifications */}
        <section className="card">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-4)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
              <History size={18} color="var(--text-muted)" />
              <h2 style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>
                Histórico de Disparos Forçados
              </h2>
            </div>
            <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)' }}>
              Auditoria de alertas emitidos
            </span>
          </div>

          {notificationsHistory.length === 0 ? (
            <p style={{ textAlign: 'center', color: 'var(--text-muted)', fontSize: 'var(--text-sm)', padding: 20 }}>
              Nenhuma notificação forçada emitida até o momento.
            </p>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              {notificationsHistory.map((item) => (
                <div
                  key={item.id}
                  style={{
                    padding: '12px 14px', background: 'var(--surface-2)', borderRadius: 'var(--radius-md)',
                    border: '1px solid var(--border)', display: 'flex', flexDirection: 'column', gap: 4
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                    <span style={{ fontWeight: 700, fontSize: 'var(--text-sm)', color: '#FFFFFF' }}>
                      {item.title}
                    </span>
                    <span className="chip chip-ok" style={{ fontSize: 10, padding: '2px 8px' }}>
                      <CheckCircle2 size={10} />
                      Enviada
                    </span>
                  </div>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', lineHeight: 1.4 }}>
                    {item.body}
                  </p>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginTop: 4, fontSize: 11, color: 'var(--text-subtle)' }}>
                    <span>
                      📅 {new Date(item.created_at).toLocaleDateString('pt-BR')} às {new Date(item.created_at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
                    </span>
                    <span>
                      🎯 Escopo: {item.target_scope === 'all' ? 'Todos Aparelhos' : 'Organização'}
                    </span>
                    <span>
                      📱 Aparelhos: {item.total_tokens || 1}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>

      </div>
    </main>
  );
}
