/**
 * Motor de parsing determinístico de comandos para o Assistente Cronos.
 * Extrai comandos, consultas financeiras e tarefas operacionais diretamente,
 * EVITANDO o consumo desnecessário de IA e garantindo resposta instantânea com custo zero.
 */

import { formatCurrency, formatDate, daysToDate, calcInterestPaid, extractBoletoData } from './utils';
import type { BillView, Supplier, Category } from '../types/database';

export interface AssistantDraftBill {
  [key: string]: any;
  beneficiary_name: string;
  amount: number | null;
  due_date: string | null;
  barcode_line?: string | null;
  supplier_id?: string | null;
  category_id?: string | null;
  description?: string;
}

export interface AssistantResponse {
  content: string;
  source: 'parser' | 'ai';
  model?: string;
  action?: {
    label: string;
    route?: string;
    executeAction?: 'mark_paid' | 'create_bill';
    billId?: string;
    draftBill?: AssistantDraftBill;
  };
  metrics?: {
    total?: number;
    count?: number;
    highlight?: string;
  };
  draftBill?: AssistantDraftBill;
}

export type ParseResult =
  | { type: 'handled'; response: AssistantResponse }
  | { type: 'needs_ai' };

/**
 * Normaliza datas nos formatos DD/MM/YYYY, DD/MM, YYYY-MM-DD para YYYY-MM-DD
 */
function normalizeDateInput(raw: string): string | null {
  const clean = raw.trim();
  const today = new Date();
  const currentYear = today.getFullYear();

  if (clean.toLowerCase() === 'hoje') {
    return today.toISOString().split('T')[0];
  }
  if (clean.toLowerCase() === 'amanhã' || clean.toLowerCase() === 'amanha') {
    const tmr = new Date(today);
    tmr.setDate(tmr.getDate() + 1);
    return tmr.toISOString().split('T')[0];
  }

  // DD/MM/YYYY
  const ddmmyyyy = clean.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
  if (ddmmyyyy) {
    const d = ddmmyyyy[1].padStart(2, '0');
    const m = ddmmyyyy[2].padStart(2, '0');
    const y = ddmmyyyy[3];
    return `${y}-${m}-${d}`;
  }

  // DD/MM (assume ano atual)
  const ddmm = clean.match(/^(\d{1,2})[/-](\d{1,2})$/);
  if (ddmm) {
    const d = ddmm[1].padStart(2, '0');
    const m = ddmm[2].padStart(2, '0');
    return `${currentYear}-${m}-${d}`;
  }

  // YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(clean)) {
    return clean;
  }

  return null;
}

/**
 * Converte strings de valor como "150", "150,50", "1.500,00", "R$ 450" em número
 */
function parseAmountInput(raw: string): number | null {
  if (!raw) return null;
  const cleaned = raw.replace(/[^\d,\.]/g, '').trim();
  if (!cleaned) return null;

  if (cleaned.includes(',') && cleaned.includes('.')) {
    // 1.500,50 -> 1500.50
    const normalized = cleaned.replace(/\./g, '').replace(',', '.');
    const n = parseFloat(normalized);
    return isNaN(n) ? null : n;
  }

  if (cleaned.includes(',')) {
    // 150,50 -> 150.50
    const n = parseFloat(cleaned.replace(',', '.'));
    return isNaN(n) ? null : n;
  }

  const n = parseFloat(cleaned);
  return isNaN(n) ? null : n;
}

/**
 * Analisa e extrai comandos de texto do usuário
 */
export function parseAssistantCommand(
  text: string,
  bills: BillView[],
  suppliers: Supplier[],
  categories: Category[]
): ParseResult {
  const trimmed = text.trim();
  const q = trimmed.toLowerCase();

  // ─────────────────────────────────────────────────────────────
  // 1. LINHA DIGITÁVEL / CÓDIGO DE BARRAS DIRETO (47 ou 48 dígitos)
  // ─────────────────────────────────────────────────────────────
  const rawDigits = trimmed.replace(/\D/g, '');
  if (rawDigits.length === 47 || rawDigits.length === 48) {
    const boletoData = extractBoletoData(rawDigits);
    if (boletoData) {
      const draft: AssistantDraftBill = {
        beneficiary_name: boletoData.bankName || 'Boleto Bancário',
        amount: boletoData.amount,
        due_date: boletoData.dueDate,
        barcode_line: boletoData.barcodeLine,
        description: `Boleto identificado via linha digitável: ${boletoData.formattedLine}`,
      };

      const amountFormatted = boletoData.amount ? formatCurrency(boletoData.amount) : 'Não identificado no código';
      const dueFormatted = boletoData.dueDate ? formatDate(boletoData.dueDate) : 'Não identificado no código';

      return {
        type: 'handled',
        response: {
          content: `Código de barras bancário detectado com sucesso!\n\n` +
            `• Instituição: ${boletoData.bankName}\n` +
            `• Valor: ${amountFormatted}\n` +
            `• Vencimento: ${dueFormatted}\n` +
            `• Linha digitável: ${boletoData.formattedLine}`,
          source: 'parser',
          draftBill: draft,
          action: {
            label: 'Confirmar e Cadastrar Boleto',
            executeAction: 'create_bill',
            draftBill: draft,
          },
          metrics: boletoData.amount ? { total: boletoData.amount, highlight: 'Boleto detectado' } : undefined,
        },
      };
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 2. DAR BAIXA / QUITAR BOLETO POR COMANDO DE TEXTO
  // Ex: "pagar boleto Casio", "dar baixa no boleto 450", "quitar conta Cemig"
  // ─────────────────────────────────────────────────────────────
  const payMatch = q.match(/^(?:pagar|dar baixa(?:\s+no)?|quitar|liquidar|marcar como pago)\s+(?:boleto|conta)?\s*(.+)$/i);
  if (payMatch) {
    const targetQuery = payMatch[1].trim();

    // Procurar nos boletos pendentes por beneficiário ou ID
    const pendingBills = bills.filter(b => b.status === 'pending');
    const matched = pendingBills.find(b => {
      const name = (b.beneficiary_name || '').toLowerCase();
      const desc = (b.description || '').toLowerCase();
      const supName = (b.supplier_name || '').toLowerCase();
      const target = targetQuery.toLowerCase();
      return name.includes(target) || desc.includes(target) || supName.includes(target) || b.id === targetQuery;
    });

    if (matched) {
      return {
        type: 'handled',
        response: {
          content: `Encontrei o boleto em aberto de **${matched.beneficiary_name || 'Boleto'}** no valor de **${formatCurrency(Number(matched.amount))}** com vencimento para **${formatDate(matched.due_date)}**.\n\nDeseja confirmar a baixa agora?`,
          source: 'parser',
          action: {
            label: `Confirmar Baixa: ${formatCurrency(Number(matched.amount))}`,
            executeAction: 'mark_paid',
            billId: matched.id,
          },
          metrics: {
            total: Number(matched.amount),
            highlight: 'Pronto para quitação',
          },
        },
      };
    } else {
      return {
        type: 'handled',
        response: {
          content: `Não encontrei nenhum boleto em aberto correspondente a "${targetQuery}". Verifique se o nome do fornecedor está correto ou consulte a lista geral.`,
          source: 'parser',
          action: { label: 'Ver todos os boletos', route: '/boletos' },
        },
      };
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 3. ADICIONAR BOLETO POR COMANDO DE TEXTO SIMPLES
  // Ex: "adicionar boleto de R$ 150 para Casio vence dia 25/11"
  // Ex: "novo boleto Casio 450 2026-11-20"
  // Ex: "cadastrar conta Cemig 320 dia 10/11"
  // ─────────────────────────────────────────────────────────────
  if (
    q.startsWith('adicionar boleto') ||
    q.startsWith('novo boleto') ||
    q.startsWith('cadastrar boleto') ||
    q.startsWith('criar boleto') ||
    q.startsWith('cadastrar conta') ||
    q.startsWith('adicionar conta')
  ) {
    // Tentar extrair valor
    const amountMatch = trimmed.match(/(?:r\$\s*)?(\d+(?:[.,]\d{1,2})?)/i);
    const dateMatch = trimmed.match(/(\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?|\d{4}-\d{2}-\d{2}|hoje|amanhã|amanha)/i);

    // Tentar extrair fornecedor comparando com a lista
    let matchedSupplier: Supplier | undefined;
    for (const s of suppliers) {
      if (q.includes(s.name.toLowerCase())) {
        matchedSupplier = s;
        break;
      }
    }

    // Tentar extrair categoria comparando com a lista
    let matchedCategory: Category | undefined;
    for (const c of categories) {
      if (q.includes(c.name.toLowerCase())) {
        matchedCategory = c;
        break;
      }
    }

    // Tentar identificar beneficiário se não achou fornecedor
    let beneficiaryName = matchedSupplier ? matchedSupplier.name : '';
    if (!beneficiaryName) {
      // Pega palavras após "para" ou "de"
      const nameAfterPara = trimmed.match(/(?:para|de|fornecedor)\s+([a-zA-Z0-9À-ÿ\s]+?)(?:\s+(?:vence|vencimento|valor|dia|r\$|\d))/i);
      if (nameAfterPara) {
        beneficiaryName = nameAfterPara[1].trim();
      } else {
        beneficiaryName = 'Novo Fornecedor';
      }
    }

    const parsedAmount = amountMatch ? parseAmountInput(amountMatch[1]) : null;
    const parsedDate = dateMatch ? normalizeDateInput(dateMatch[1]) : null;

    if (parsedAmount && parsedDate) {
      const draft: AssistantDraftBill = {
        beneficiary_name: beneficiaryName,
        amount: parsedAmount,
        due_date: parsedDate,
        supplier_id: matchedSupplier?.id || null,
        category_id: matchedCategory?.id || null,
        description: `Boleto cadastrado via comando rápido no chat`,
      };

      return {
        type: 'handled',
        response: {
          content: `Comando de cadastro interpretado com sucesso!\n\n` +
            `• Beneficiário: ${beneficiaryName}\n` +
            `• Valor: ${formatCurrency(parsedAmount)}\n` +
            `• Vencimento: ${formatDate(parsedDate)}\n\n` +
            `Clique abaixo para salvar diretamente no banco de dados.`,
          source: 'parser',
          draftBill: draft,
          action: {
            label: 'Salvar Boleto no Sistema',
            executeAction: 'create_bill',
            draftBill: draft,
          },
          metrics: {
            total: parsedAmount,
            highlight: 'Novo boleto pronto',
          },
        },
      };
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 4. CONSULTAS FINANCEIRAS ESTATÍSTICAS DIRETAS (SEM IA)
  // ─────────────────────────────────────────────────────────────

  // Atrasados / Vencidos
  if (q.includes('atrasad') || q.includes('vencid') || q.includes('venceu') || q.includes('em atraso')) {
    const overdue = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) < 0);
    const total = overdue.reduce((sum, b) => sum + Number(b.amount), 0);

    if (overdue.length === 0) {
      return {
        type: 'handled',
        response: {
          content: 'Excelente notícia! Não há nenhum boleto atrasado na sua empresa no momento. Tudo está em dia.',
          source: 'parser',
          action: { label: 'Ver todos os boletos', route: '/boletos' },
        },
      };
    }

    const listSample = overdue
      .slice(0, 4)
      .map(b => `• **${b.beneficiary_name || 'Boleto'}**: ${formatCurrency(Number(b.amount))} (venceu ${formatDate(b.due_date)})`)
      .join('\n');

    return {
      type: 'handled',
      response: {
        content: `Você possui **${overdue.length} boleto${overdue.length > 1 ? 's' : ''} atrasado${overdue.length > 1 ? 's' : ''}**, totalizando **${formatCurrency(total)}**:\n\n${listSample}${overdue.length > 4 ? `\n... e mais ${overdue.length - 4} conta(s).` : ''}`,
        source: 'parser',
        action: { label: 'Visualizar boletos atrasados', route: '/boletos' },
        metrics: { total, count: overdue.length, highlight: 'Atenção imediata' },
      },
    };
  }

  // Vencendo Hoje
  if (q.includes('hoje')) {
    const todayBills = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) === 0);
    const total = todayBills.reduce((sum, b) => sum + Number(b.amount), 0);

    if (todayBills.length === 0) {
      return {
        type: 'handled',
        response: {
          content: 'Nenhum boleto vence hoje! Nada pendente para quitação imediata nas próximas horas.',
          source: 'parser',
        },
      };
    }

    const listSample = todayBills
      .map(b => `• **${b.beneficiary_name || 'Boleto'}**: ${formatCurrency(Number(b.amount))}`)
      .join('\n');

    return {
      type: 'handled',
      response: {
        content: `Hoje você precisa pagar **${todayBills.length} boleto${todayBills.length > 1 ? 's' : ''}**, somando **${formatCurrency(total)}**:\n\n${listSample}`,
        source: 'parser',
        action: { label: 'Abrir boletos de hoje', route: '/boletos' },
        metrics: { total, count: todayBills.length, highlight: 'Vence hoje' },
      },
    };
  }

  // Vencendo Amanhã
  if (q.includes('amanhã') || q.includes('amanha')) {
    const tomorrowBills = bills.filter(b => b.status === 'pending' && daysToDate(b.due_date) === 1);
    const total = tomorrowBills.reduce((sum, b) => sum + Number(b.amount), 0);

    if (tomorrowBills.length === 0) {
      return {
        type: 'handled',
        response: {
          content: 'Não há boletos com vencimento marcado para amanhã.',
          source: 'parser',
        },
      };
    }

    const listSample = tomorrowBills
      .map(b => `• **${b.beneficiary_name || 'Boleto'}**: ${formatCurrency(Number(b.amount))}`)
      .join('\n');

    return {
      type: 'handled',
      response: {
        content: `Amanhã vence${tomorrowBills.length > 1 ? 'm' : ''} **${tomorrowBills.length} boleto${tomorrowBills.length > 1 ? 's' : ''}**, totalizando **${formatCurrency(total)}**:\n\n${listSample}`,
        source: 'parser',
        action: { label: 'Ver lista de boletos', route: '/boletos' },
        metrics: { total, count: tomorrowBills.length, highlight: 'Vence amanhã' },
      },
    };
  }

  // Próximos 7 dias / Semana
  if (q.includes('semana') || q.includes('7 dias') || q.includes('sete dias')) {
    const thisWeek = bills.filter(b => {
      if (b.status !== 'pending') return false;
      const days = daysToDate(b.due_date);
      return days >= 0 && days <= 7;
    });
    const total = thisWeek.reduce((sum, b) => sum + Number(b.amount), 0);

    if (thisWeek.length === 0) {
      return {
        type: 'handled',
        response: {
          content: 'Você não tem nenhum boleto agendado para vencer nos próximos 7 dias. Seu fluxo de caixa está tranquilo!',
          source: 'parser',
          action: { label: 'Ver contas do mês', route: '/boletos' },
        },
      };
    }

    const listSample = thisWeek
      .slice(0, 5)
      .map(b => `• **${b.beneficiary_name || 'Boleto'}**: ${formatCurrency(Number(b.amount))} (${formatDate(b.due_date)})`)
      .join('\n');

    return {
      type: 'handled',
      response: {
        content: `Para os próximos 7 dias, há **${thisWeek.length} boleto${thisWeek.length > 1 ? 's' : ''}** a pagar, totalizando **${formatCurrency(total)}**:\n\n${listSample}`,
        source: 'parser',
        action: { label: 'Ver boletos da semana', route: '/boletos' },
        metrics: { total, count: thisWeek.length, highlight: 'Próximos 7 dias' },
      },
    };
  }

  // Juros e Multas
  if (q.includes('juros') || q.includes('multa')) {
    const paidBills = bills.filter(b => b.status === 'paid');
    const totalInterest = paidBills.reduce((acc, b) => acc + calcInterestPaid(Number(b.amount), b.paid_amount), 0);

    if (totalInterest === 0) {
      return {
        type: 'handled',
        response: {
          content: 'Parabéns! Nenhum centavo de juros ou multa foi pago em boletos no período registrado. Sua pontualidade está gerando economia máxima!',
          source: 'parser',
          action: { label: 'Ver relatórios financeiros', route: '/relatorios' },
        },
      };
    }

    return {
      type: 'handled',
      response: {
        content: `No acumulado, a empresa pagou um total de **${formatCurrency(totalInterest)}** em juros e multas por atraso. Pagar no vencimento garante economia direta.`,
        source: 'parser',
        action: { label: 'Consultar relatório detalhado', route: '/relatorios' },
        metrics: { total: totalInterest, highlight: 'Juros acumulados' },
      },
    };
  }

  // Mês Atual / Resumo do Mês
  if (q.includes('mês') || q.includes('mes')) {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthBills = bills.filter(b => {
      const d = new Date(b.due_date + 'T00:00:00');
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const pending = monthBills.filter(b => b.status === 'pending');
    const paid = monthBills.filter(b => b.status === 'paid');
    const totalPending = pending.reduce((sum, b) => sum + Number(b.amount), 0);
    const totalPaid = paid.reduce((sum, b) => sum + (b.paid_amount ?? Number(b.amount)), 0);

    return {
      type: 'handled',
      response: {
        content: `Visão geral deste mês:\n\n` +
          `• **A pagar (pendente)**: ${formatCurrency(totalPending)} (${pending.length} boletos)\n` +
          `• **Já pago**: ${formatCurrency(totalPaid)} (${paid.length} boletos)`,
        source: 'parser',
        action: { label: 'Ver dashboard completo', route: '/' },
        metrics: { total: totalPending, highlight: 'A pagar no mês' },
      },
    };
  }

  // Boletos já pagos / Quitados
  if (q.includes('já pago') || q.includes('ja pago') || q.includes('pagos') || q.includes('quitados')) {
    const paidBills = bills.filter(b => b.status === 'paid');
    const totalPaid = paidBills.reduce((sum, b) => sum + (b.paid_amount ?? Number(b.amount)), 0);

    return {
      type: 'handled',
      response: {
        content: `A empresa já quitou **${paidBills.length} boleto${paidBills.length > 1 ? 's' : ''}**, somando **${formatCurrency(totalPaid)}** em pagamentos realizados.`,
        source: 'parser',
        action: { label: 'Ver relatórios de quitação', route: '/relatorios' },
        metrics: { total: totalPaid, count: paidBills.length, highlight: 'Total quitado' },
      },
    };
  }

  // Fornecedor Específico
  for (const sup of suppliers) {
    if (q.includes(sup.name.toLowerCase())) {
      const supBills = bills.filter(b => b.supplier_id === sup.id && b.status === 'pending');
      const total = supBills.reduce((sum, b) => sum + Number(b.amount), 0);

      if (supBills.length === 0) {
        return {
          type: 'handled',
          response: {
            content: `Você não tem contas pendentes para **${sup.name}**. Todos os boletos estão quitados!`,
            source: 'parser',
            action: { label: 'Ver fornecedor', route: '/fornecedores' },
          },
        };
      }

      const listSample = supBills
        .slice(0, 3)
        .map(b => `• **${b.beneficiary_name}**: ${formatCurrency(Number(b.amount))} (${formatDate(b.due_date)})`)
        .join('\n');

      return {
        type: 'handled',
        response: {
          content: `Você deve **${formatCurrency(total)}** para **${sup.name}**, distribuídos em **${supBills.length} boleto(s)** em aberto:\n\n${listSample}`,
          source: 'parser',
          action: { label: `Ver boletos de ${sup.name}`, route: '/boletos' },
          metrics: { total, count: supBills.length, highlight: sup.name },
        },
      };
    }
  }

  // Comandos de navegação direta
  if (q === 'boletos' || q === 'ver boletos' || q === 'listar boletos' || q === 'abrir boletos') {
    return {
      type: 'handled',
      response: {
        content: 'Abrindo a listagem completa de boletos da sua organização.',
        source: 'parser',
        action: { label: 'Ir para Boletos', route: '/boletos' },
      },
    };
  }

  if (q === 'relatórios' || q === 'relatorios' || q === 'abrir relatórios' || q === 'gráficos') {
    return {
      type: 'handled',
      response: {
        content: 'Abrindo a central de relatórios financeiros e projeção de caixa.',
        source: 'parser',
        action: { label: 'Ir para Relatórios', route: '/relatorios' },
      },
    };
  }

  if (q === 'fornecedores' || q === 'abrir fornecedores') {
    return {
      type: 'handled',
      response: {
        content: 'Abrindo o gerenciamento de fornecedores e parceiros.',
        source: 'parser',
        action: { label: 'Ir para Fornecedores', route: '/fornecedores' },
      },
    };
  }

  // Ajuda / Comandos suportados
  if (q === 'ajuda' || q === 'comandos' || q === 'o que você faz' || q === 'help') {
    return {
      type: 'handled',
      response: {
        content: `Aqui estão alguns comandos que executo instantaneamente sem consumir IA:\n\n` +
          `• **Consultas**: "O que vence hoje?", "Quais boletos estão atrasados?", "Contas da semana", "Resumo do mês"\n` +
          `• **Por fornecedor**: "Quanto devo para Casio?", "Boletos do Seiko"\n` +
          `• **Dar baixa rápida**: "Pagar boleto Casio", "Dar baixa no boleto Cemig"\n` +
          `• **Adicionar rápido**: "Adicionar boleto Casio 450 dia 25/11"\n` +
          `• **Código de barras**: Basta colar os 47 ou 48 números do código!\n` +
          `• **Upload de Foto**: Envie a foto ou print de um boleto pelo botão de clipe para extração automática via visão IA (gpt-5.4-mini).\n\n` +
          `Para perguntas abertas ou conselhos financeiros, respondo via inteligência artificial conectada à base real.`,
        source: 'parser',
      },
    };
  }

  // Se nenhum padrão foi atendido determinísticamente, delega para a IA (OpenAI gpt-5.4-mini)
  return { type: 'needs_ai' };
}
