import { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from '../components/Toast';
import { supabase } from '../lib/supabase';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft, Building2, User, LogOut, Trash2, AlertCircle,
  Shield, Save, ChevronRight, Sun, Moon, Sparkles, Key, Eye, EyeOff,
} from 'lucide-react';
import { useMutation } from '@tanstack/react-query';
import { getOpenAiApiKey, setOpenAiApiKey } from '../lib/openai';

export default function SettingsPage() {
  const { user, currentOrg, signOut } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleteConfirm, setDeleteConfirm] = useState('');
  const [orgName, setOrgName] = useState(currentOrg?.organization?.name ?? '');
  const [savingOrg, setSavingOrg] = useState(false);

  // OpenAI key local configuration
  const [apiKeyInput, setApiKeyInput] = useState(() => getOpenAiApiKey());
  const [showApiKey, setShowApiKey] = useState(false);
  const [savedKeyExists, setSavedKeyExists] = useState(() => !!getOpenAiApiKey());

  function handleSaveApiKey() {
    setOpenAiApiKey(apiKeyInput);
    setSavedKeyExists(!!apiKeyInput.trim());
    toast(apiKeyInput.trim() ? 'Chave da OpenAI salva com sucesso no navegador!' : 'Chave removida.', 'success');
  }

  const firstName = user?.user_metadata?.full_name?.split(' ')[0] ?? user?.email?.split('@')[0] ?? 'Usuário';

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('cronos-theme') as 'dark' | 'light') || 'dark';
  });

  function handleThemeChange(newTheme: 'dark' | 'light') {
    setTheme(newTheme);
    localStorage.setItem('cronos-theme', newTheme);
    if (newTheme === 'light') {
      document.documentElement.setAttribute('data-theme', 'light');
    } else {
      document.documentElement.removeAttribute('data-theme');
    }
    toast(`Tema ${newTheme === 'light' ? 'Claro' : 'Escuro'} ativado!`, 'info');
  }

  async function handleSaveOrgName() {
    if (!currentOrg?.org_id || !orgName.trim()) return;
    setSavingOrg(true);
    const { error } = await supabase
      .from('organizations')
      .update({ name: orgName.trim() })
      .eq('id', currentOrg.org_id);
    setSavingOrg(false);
    if (error) {
      toast('Erro ao salvar o nome da empresa.', 'error');
    } else {
      toast('Nome da empresa atualizado!', 'success');
    }
  }

  const deleteAccountMutation = useMutation({
    mutationFn: async () => {
      // In a real app, call an Edge Function that handles LGPD data deletion
      await signOut();
    },
    onSuccess: () => {
      navigate('/login');
      toast('Conta encerrada. Seus dados foram removidos.', 'info');
    },
    onError: () => toast('Erro ao excluir a conta. Contate o suporte.', 'error'),
  });

  const DELETE_PHRASE = 'EXCLUIR CONTA';

  return (
    <main className="page" id="page-settings">
      <header className="page-header">
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <button className="btn-ghost btn-icon" onClick={() => navigate(-1)} aria-label="Voltar"
            style={{ width: 40, height: 40, minHeight: 40 }}>
            <ArrowLeft size={20} />
          </button>
          <h1 style={{ fontSize: 'var(--text-lg)', fontWeight: 700, flex: 1 }}>Configurações</h1>
        </div>
      </header>

      <div className="page-content container">
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>

          {/* Profile section */}
          <section className="card" aria-labelledby="profile-heading">
            <h2 id="profile-heading" style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-4)' }}>
              Perfil
            </h2>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-4)', marginBottom: 'var(--space-4)' }}>
              <div style={{
                width: 60, height: 60, borderRadius: 'var(--radius-full)',
                background: 'var(--brand)', display: 'flex',
                alignItems: 'center', justifyContent: 'center', flexShrink: 0,
              }}>
                <span style={{ fontFamily: 'Montserrat', fontSize: 'var(--text-xl)', fontWeight: 900, color: 'var(--on-brand)' }}>
                  {firstName.charAt(0).toUpperCase()}
                </span>
              </div>
              <div>
                <p style={{ fontWeight: 700, fontSize: 'var(--text-base)' }}>{user?.user_metadata?.full_name ?? firstName}</p>
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>{user?.email}</p>
                <span className="chip chip-brand" style={{ marginTop: 'var(--space-1)' }}>
                  {currentOrg?.role === 'owner' ? 'Dono' : currentOrg?.role === 'finance' ? 'Financeiro' : 'Somente leitura'}
                </span>
              </div>
            </div>

            <div style={{ display: 'flex', alignItems: 'center', padding: 'var(--space-3)', background: 'var(--surface-2)', borderRadius: 'var(--radius-md)', gap: 'var(--space-3)' }}>
              <User size={16} color="var(--text-muted)" />
              <div style={{ flex: 1 }}>
                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Alterar senha</p>
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-subtle)' }}>Enviamos um link para o seu e-mail</p>
              </div>
              <button
                className="btn btn-secondary btn-sm"
                onClick={async () => {
                  if (!user?.email) return;
                  await supabase.auth.resetPasswordForEmail(user.email);
                  toast('Link de redefinição enviado para ' + user.email, 'success');
                }}
              >
                Enviar link
              </button>
            </div>
          </section>

          {/* Organization section */}
          {currentOrg?.role === 'owner' && (
            <section className="card" aria-labelledby="org-heading">
              <h2 id="org-heading" style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-4)' }}>
                Empresa
              </h2>
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-4)' }}>
                <Building2 size={16} color="var(--text-muted)" />
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>Morpheus Relojoaria</p>
              </div>
              <div className="input-group">
                <label htmlFor="org-name" className="input-label">Nome da empresa</label>
                <input
                  id="org-name"
                  type="text"
                  className="input"
                  value={orgName}
                  onChange={e => setOrgName(e.target.value)}
                />
              </div>
              <button
                className="btn btn-secondary"
                style={{ marginTop: 'var(--space-3)' }}
                onClick={handleSaveOrgName}
                disabled={savingOrg}
              >
                <Save size={16} />
                {savingOrg ? 'Salvando...' : 'Salvar nome'}
              </button>
            </section>
          )}

          {/* Appearance & Theme */}
          <section className="card" aria-labelledby="appearance-heading">
            <h2 id="appearance-heading" style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-4)' }}>
              Aparência e Tema
            </h2>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>
              <button
                type="button"
                onClick={() => handleThemeChange('dark')}
                className={`card ${theme === 'dark' ? 'active-border' : ''}`}
                style={{
                  padding: 'var(--space-3)',
                  border: theme === 'dark' ? '2px solid var(--brand)' : '1px solid var(--border)',
                  background: 'var(--surface-2)',
                  borderRadius: 'var(--radius-md)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 'var(--space-3)',
                  cursor: 'pointer',
                  textAlign: 'left',
                }}
                aria-pressed={theme === 'dark'}
              >
                <div style={{
                  width: 36, height: 36, borderRadius: 'var(--radius-md)',
                  background: 'rgba(255, 242, 26, 0.12)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  <Moon size={18} color="var(--brand)" />
                </div>
                <div>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', color: 'var(--text)', margin: 0 }}>Modo Escuro</p>
                  <p style={{ fontSize: 11, color: 'var(--text-muted)', margin: 0 }}>OLED / Luxo</p>
                </div>
              </button>

              <button
                type="button"
                onClick={() => handleThemeChange('light')}
                className={`card ${theme === 'light' ? 'active-border' : ''}`}
                style={{
                  padding: 'var(--space-3)',
                  border: theme === 'light' ? '2px solid var(--brand)' : '1px solid var(--border)',
                  background: 'var(--surface-2)',
                  borderRadius: 'var(--radius-md)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 'var(--space-3)',
                  cursor: 'pointer',
                  textAlign: 'left',
                }}
                aria-pressed={theme === 'light'}
              >
                <div style={{
                  width: 36, height: 36, borderRadius: 'var(--radius-md)',
                  background: 'rgba(197, 155, 39, 0.15)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  <Sun size={18} color="var(--brand)" />
                </div>
                <div>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)', color: 'var(--text)', margin: 0 }}>Modo Claro</p>
                  <p style={{ fontSize: 11, color: 'var(--text-muted)', margin: 0 }}>Dia / Alta luz</p>
                </div>
              </button>
            </div>
          </section>

          {/* AI Settings Section */}
          <section className="card" aria-labelledby="ai-heading">
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 'var(--space-3)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                <Sparkles size={16} color="var(--brand)" />
                <h2 id="ai-heading" style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em', margin: 0 }}>
                  Inteligência Artificial (OpenAI)
                </h2>
              </div>
              <span className={`chip ${savedKeyExists ? 'chip-brand' : 'chip-dim'}`} style={{ fontSize: 10 }}>
                {savedKeyExists ? 'Chave Ativa' : 'Não configurada'}
              </span>
            </div>

            <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginBottom: 'var(--space-3)', lineHeight: 1.5 }}>
              Para habilitar o Assistente Cronos com <strong>gpt-5.4-mini</strong> e a leitura óptica de boletos por imagem, insira sua chave da OpenAI. Ela fica armazenada <strong>apenas no seu navegador local</strong> e nunca é exposta em repositórios ou compilações públicas.
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                <Key size={16} color="var(--text-subtle)" style={{ position: 'absolute', left: 12, pointerEvents: 'none' }} />
                <input
                  id="openai-api-key-input"
                  type={showApiKey ? 'text' : 'password'}
                  className="input"
                  placeholder="Cole sua chave OpenAI aqui..."
                  value={apiKeyInput}
                  onChange={e => setApiKeyInput(e.target.value)}
                  style={{ paddingLeft: 38, paddingRight: 40, fontFamily: 'monospace', fontSize: 13, width: '100%' }}
                />
                <button
                  type="button"
                  className="btn-ghost btn-icon"
                  onClick={() => setShowApiKey(!showApiKey)}
                  aria-label={showApiKey ? 'Ocultar chave' : 'Mostrar chave'}
                  style={{ position: 'absolute', right: 6, width: 32, height: 32, minHeight: 32, padding: 0 }}
                >
                  {showApiKey ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-2)', marginTop: 'var(--space-1)' }}>
                <button
                  id="btn-save-openai-key"
                  className="btn-primary"
                  onClick={handleSaveApiKey}
                  style={{ flex: 1, padding: '8px 16px', fontSize: 'var(--text-sm)' }}
                >
                  <Save size={14} />
                  Salvar chave local
                </button>
                {savedKeyExists && (
                  <button
                    className="btn-secondary"
                    onClick={() => {
                      setApiKeyInput('');
                      setOpenAiApiKey('');
                      setSavedKeyExists(false);
                      toast('Chave removida.', 'info');
                    }}
                    style={{ padding: '8px 16px', fontSize: 'var(--text-sm)' }}
                  >
                    Remover
                  </button>
                )}
              </div>
            </div>
          </section>

          {/* Security section */}
          <section className="card" aria-labelledby="security-heading">
            <h2 id="security-heading" style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-4)' }}>
              Segurança e privacidade
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', padding: 'var(--space-3)', background: 'var(--surface-2)', borderRadius: 'var(--radius-md)' }}>
                <Shield size={16} color="var(--ok)" />
                <p style={{ flex: 1, fontSize: 'var(--text-sm)' }}>Dados criptografados em trânsito e em repouso</p>
              </div>
              <button
                className="card card-hover"
                style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', textAlign: 'left', cursor: 'pointer', border: '1px solid var(--border)', background: 'var(--surface)', color: 'var(--text)', width: '100%' }}
                onClick={() => toast('Seus dados serão exportados e enviados por e-mail em até 24h.', 'info')}
              >
                <div style={{ flex: 1 }}>
                  <p style={{ fontWeight: 600, fontSize: 'var(--text-sm)' }}>Exportar meus dados (LGPD)</p>
                  <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>Receba todos os seus dados por e-mail</p>
                </div>
                <ChevronRight size={16} color="var(--text-subtle)" />
              </button>
            </div>
          </section>

          {/* App info */}
          <section className="card">
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>Versão</span>
                <span style={{ fontSize: 'var(--text-sm)', fontWeight: 600 }}>1.0.0</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>Produto</span>
                <span style={{ fontSize: 'var(--text-sm)', fontWeight: 600 }}>Cronos</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>Cliente</span>
                <span style={{ fontSize: 'var(--text-sm)', fontWeight: 600 }}>Morpheus Relojoaria</span>
              </div>
            </div>
          </section>

          {/* Danger zone */}
          <section className="card" style={{ borderColor: 'rgba(255, 77, 77, 0.3)' }} aria-labelledby="danger-heading">
            <h2 id="danger-heading" style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: 'var(--urgent)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 'var(--space-4)' }}>
              Zona de perigo
            </h2>
            <button
              id="btn-logout"
              className="btn btn-secondary btn-full"
              onClick={async () => { await signOut(); navigate('/login'); }}
              style={{ marginBottom: 'var(--space-3)' }}
            >
              <LogOut size={16} />
              Sair da conta
            </button>
            <button
              id="btn-delete-account"
              className="btn btn-danger btn-full"
              onClick={() => setShowDeleteModal(true)}
            >
              <Trash2 size={16} />
              Excluir conta e dados
            </button>
          </section>
        </div>
      </div>

      {/* Delete account confirmation */}
      {showDeleteModal && (
        <div
          className="modal-overlay"
          onClick={e => e.target === e.currentTarget && setShowDeleteModal(false)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="delete-account-title"
        >
          <div className="modal-sheet">
            <div className="modal-handle" aria-hidden="true" />
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginBottom: 'var(--space-4)' }}>
              <div style={{ width: 48, height: 48, borderRadius: 'var(--radius-full)', background: 'var(--urgent-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <AlertCircle size={24} color="var(--urgent)" />
              </div>
              <div>
                <h2 id="delete-account-title" style={{ fontSize: 'var(--text-base)', fontWeight: 700 }}>Excluir conta?</h2>
                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--urgent)' }}>Esta ação é irreversível</p>
              </div>
            </div>
            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', marginBottom: 'var(--space-4)', lineHeight: 1.6 }}>
              Todos os seus dados serão removidos permanentemente, incluindo boletos, anexos e histórico. Esta ação não pode ser desfeita.
            </p>

            <div className="input-group" style={{ marginBottom: 'var(--space-4)' }}>
              <label htmlFor="delete-confirm" className="input-label">
                Digite <strong style={{ color: 'var(--urgent)' }}>{DELETE_PHRASE}</strong> para confirmar
              </label>
              <input
                id="delete-confirm"
                type="text"
                className="input"
                value={deleteConfirm}
                onChange={e => setDeleteConfirm(e.target.value)}
                placeholder={DELETE_PHRASE}
              />
            </div>

            <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowDeleteModal(false)}>
                Cancelar
              </button>
              <button
                id="btn-confirm-delete-account"
                className="btn btn-danger"
                style={{ flex: 1 }}
                onClick={() => deleteAccountMutation.mutate()}
                disabled={deleteConfirm !== DELETE_PHRASE || deleteAccountMutation.isPending}
              >
                {deleteAccountMutation.isPending ? 'Excluindo...' : 'Excluir tudo'}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}
