import { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useToast } from './Toast';
import { configureFcmDevice, isPushNotificationSupported } from '../lib/firebase';
import {
  BellRing, X, Clock, ShieldCheck, AlertCircle,
  Smartphone
} from 'lucide-react';

export function NotificationPermissionPrompt() {
  const { user, currentOrg } = useAuth();
  const { toast } = useToast();

  const [permission, setPermission] = useState<NotificationPermission | 'unsupported'>(() => {
    if (typeof window === 'undefined' || !('Notification' in window)) return 'unsupported';
    return Notification.permission;
  });

  const [visible, setVisible] = useState(false);
  const [loading, setLoading] = useState(false);

  // Verification on startup / mount
  useEffect(() => {
    if (!isPushNotificationSupported()) return;

    const currentPerm = Notification.permission;
    setPermission(currentPerm);

    // If permission is already granted, automatically sync FCM token and device info silently
    if (currentPerm === 'granted') {
      if (user?.id) {
        configureFcmDevice(user.id, currentOrg?.org_id).catch((err) => {
          console.warn('[FCM] Auto-sync on startup notice:', err);
        });
      }
      return;
    }

    // If permission is default (never asked or pending):
    // DO NOT trigger the raw browser popup directly;
    // Show the in-app explainer modal FIRST so user understands the reason!
    if (currentPerm === 'default') {
      const isDismissed = sessionStorage.getItem('cronos_notif_prompt_dismissed') === 'true';
      if (!isDismissed) {
        // Small delay so page renders smoothly first
        const timer = setTimeout(() => {
          setVisible(true);
        }, 600);
        return () => clearTimeout(timer);
      }
    }
  }, [user?.id, currentOrg?.org_id]);

  // When user signs in and already had permission granted, ensure FCM is configured
  useEffect(() => {
    if (user?.id && permission === 'granted') {
      configureFcmDevice(user.id, currentOrg?.org_id).catch((err) => {
        console.warn('[FCM] User sign-in sync notice:', err);
      });
    }
  }, [user?.id, permission, currentOrg?.org_id]);

  // Handle user clicking the permission button in prompt
  async function handleEnableNotifications() {
    setLoading(true);
    try {
      if (!isPushNotificationSupported()) {
        toast('Notificações push não são suportadas neste navegador.', 'error');
        setVisible(false);
        return;
      }

      // Now request native browser permission (after explaining the need)
      const permResult = await Notification.requestPermission();
      setPermission(permResult);

      if (permResult === 'granted') {
        if (user?.id) {
          const res = await configureFcmDevice(user.id, currentOrg?.org_id);
          if (res.success) {
            toast('🔔 Notificações ativadas e configuradas com sucesso neste aparelho!', 'success');
          } else {
            toast(res.error || 'Permissão concedida, sincronizando dispositivo...', 'info');
          }
        } else {
          toast('Permissão concedida! As notificações serão associadas à sua conta.', 'success');
        }
        setVisible(false);
      } else if (permResult === 'denied') {
        toast('Permissão de notificação negada no navegador. Você pode habilitar nas configurações do site.', 'info');
        setVisible(false);
      } else {
        // Closed without choice
        setVisible(false);
      }
    } catch (err: any) {
      console.error('[FCM] Error enabling notifications:', err);
      toast('Não foi possível ativar notificações no momento.', 'error');
    } finally {
      setLoading(false);
    }
  }

  function handleDismiss() {
    sessionStorage.setItem('cronos_notif_prompt_dismissed', 'true');
    setVisible(false);
  }

  if (!visible) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="notif-prompt-title"
      aria-describedby="notif-prompt-desc"
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 9999,
        background: 'rgba(5, 7, 10, 0.78)',
        backdropFilter: 'blur(10px)',
        WebkitBackdropFilter: 'blur(10px)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 'var(--space-4)',
        animation: 'fadeIn 0.25s ease',
      }}
      onClick={handleDismiss}
    >
      <div
        className="card"
        style={{
          maxWidth: 480,
          width: '100%',
          background: 'var(--surface)',
          border: '1px solid var(--border-light)',
          borderRadius: 'var(--radius-xl)',
          padding: 'var(--space-6)',
          boxShadow: 'var(--shadow-lg), var(--shadow-brand)',
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--space-4)',
          position: 'relative',
          overflow: 'hidden',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Top brand accent stripe */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            height: 4,
            background: 'linear-gradient(90deg, var(--brand), #ffe600, var(--soon))',
          }}
        />

        {/* Header with icon and close button */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 'var(--space-3)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
            <div
              style={{
                width: 48,
                height: 48,
                borderRadius: 'var(--radius-lg)',
                background: 'var(--brand-dim)',
                border: '1px solid rgba(255, 242, 26, 0.3)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0 0 16px rgba(255, 242, 26, 0.25)',
                flexShrink: 0,
              }}
            >
              <BellRing size={26} color="var(--brand)" strokeWidth={2.5} />
            </div>
            <div>
              <span
                className="chip chip-brand"
                style={{ fontSize: 10, padding: '2px 8px', textTransform: 'uppercase', letterSpacing: '0.06em' }}
              >
                Morpheus Relojoaria
              </span>
              <h2
                id="notif-prompt-title"
                style={{
                  fontSize: 'var(--text-lg)',
                  fontWeight: 800,
                  margin: '4px 0 0',
                  color: 'var(--text)',
                  lineHeight: 1.2,
                }}
              >
                Por que ativar as notificações no Cronos?
              </h2>
            </div>
          </div>

          <button
            onClick={handleDismiss}
            className="btn-ghost btn-icon btn-sm"
            aria-label="Fechar aviso"
            style={{ width: 32, height: 32, padding: 4, flexShrink: 0 }}
          >
            <X size={18} />
          </button>
        </div>

        {/* Intro text explaining the purpose */}
        <p
          id="notif-prompt-desc"
          style={{
            fontSize: 'var(--text-sm)',
            color: 'var(--text-muted)',
            lineHeight: 1.6,
            margin: 0,
          }}
        >
          Para garantir o controle rigoroso do fluxo de caixa e evitar multas por atraso, o Cronos precisa enviar alertas em tempo real para este dispositivo:
        </p>

        {/* 3 Detailed reasons explaining the necessity */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
          {/* Reason 1: Bill deadlines */}
          <div
            style={{
              display: 'flex',
              alignItems: 'flex-start',
              gap: 'var(--space-3)',
              padding: '12px 14px',
              background: 'var(--surface-2)',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border)',
            }}
          >
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: 'var(--radius-sm)',
                background: 'var(--soon-bg)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
                marginTop: 2,
              }}
            >
              <Clock size={16} color="var(--soon)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-sm)', fontWeight: 700, margin: '0 0 2px', color: 'var(--text)' }}>
                Zero Multas e Juros de Boletos
              </p>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', lineHeight: 1.4, margin: 0 }}>
                Alertas automáticos com <strong>7 dias</strong>, <strong>2 dias</strong> e no <strong>dia do vencimento</strong> de contas de fornecedores (Casio, Seiko, Citizen).
              </p>
            </div>
          </div>

          {/* Reason 2: Critical forced admin alerts */}
          <div
            style={{
              display: 'flex',
              alignItems: 'flex-start',
              gap: 'var(--space-3)',
              padding: '12px 14px',
              background: 'var(--surface-2)',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border)',
            }}
          >
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: 'var(--radius-sm)',
                background: 'var(--urgent-bg)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
                marginTop: 2,
              }}
            >
              <AlertCircle size={16} color="var(--urgent)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-sm)', fontWeight: 700, margin: '0 0 2px', color: 'var(--text)' }}>
                Alertas Forçados da Administração
              </p>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', lineHeight: 1.4, margin: 0 }}>
                Avisos prioritários emitidos pelo painel administrativo para quitações imediatas ou conferências de caixa.
              </p>
            </div>
          </div>

          {/* Reason 3: Works even when closed */}
          <div
            style={{
              display: 'flex',
              alignItems: 'flex-start',
              gap: 'var(--space-3)',
              padding: '12px 14px',
              background: 'var(--surface-2)',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border)',
            }}
          >
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: 'var(--radius-sm)',
                background: 'var(--brand-dim)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
                marginTop: 2,
              }}
            >
              <Smartphone size={16} color="var(--brand)" />
            </div>
            <div>
              <p style={{ fontSize: 'var(--text-sm)', fontWeight: 700, margin: '0 0 2px', color: 'var(--text)' }}>
                Funciona Mesmo com o App Fechado
              </p>
              <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-subtle)', lineHeight: 1.4, margin: 0 }}>
                O Web Push nativo acorda seu aparelho com som e vibração para que você nunca perca uma baixa financeira.
              </p>
            </div>
          </div>
        </div>

        {/* Privacy badge */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            fontSize: 11,
            color: 'var(--text-subtle)',
            background: 'var(--surface-3)',
            padding: '8px 12px',
            borderRadius: 'var(--radius-sm)',
          }}
        >
          <ShieldCheck size={14} color="var(--ok)" style={{ flexShrink: 0 }} />
          <span>
            100% seguro: sem propagandas nem spam. Apenas alertas financeiros do seu negócio.
          </span>
        </div>

        {/* Action buttons */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)', marginTop: 'var(--space-1)' }}>
          <button
            id="btn-enable-notifications-modal"
            onClick={handleEnableNotifications}
            className="btn btn-primary btn-lg btn-full"
            disabled={loading}
            style={{
              boxShadow: 'var(--shadow-brand)',
              fontWeight: 800,
              fontSize: 'var(--text-base)',
            }}
          >
            <BellRing size={20} />
            <span>{loading ? 'Configurando no Aparelho...' : 'Permitir Notificações no Aparelho'}</span>
          </button>

          <button
            id="btn-dismiss-notifications-modal"
            onClick={handleDismiss}
            className="btn btn-ghost btn-sm"
            style={{ color: 'var(--text-subtle)', fontWeight: 500 }}
          >
            Agora não, lembrar depois
          </button>
        </div>
      </div>
    </div>
  );
}
